{
  "name": "SAO - 6º BBM Material Control",
  "description": "Sistema de controle de entrada e saída de materiais para a Seção de Apoio Operacional (SAO) do 6º Batalhão de Bombeiros Militar do CBMMG.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum MaterialType {
  TERRESTRE = "Salv. Terrestre/Altura",
  INCENDIO = "Incêndio Urbano",
  FLORESTAL = "Florestal",
  APH = "APH",
  AQUATICO = "Salv. Aquático",
  FERRAMENTAS = "Ferramentas diversas"
}

export enum MovementStatus {
  PENDENTE = "PENDENTE",
  DEVOLVIDO = "DEVOLVIDO"
}

export interface MilitaryPerson {
  bm: string;
  name: string;
  rank: string;
  cpf: string;
}

export interface Movement {
  id: string;
  bm: string;
  name: string;
  rank: string;
  dateCheckout: string;
  material: string;
  type: MaterialType;
  status: MovementStatus;
  dateReturn?: string;
  observations?: string;
  receiverBm?: string;
  receiverName?: string;
}

export interface AuthState {
  user: MilitaryPerson | null;
  isVisitor: boolean;
}

import { MilitaryPerson, MaterialType } from './types';

export const MOCK_MILITARY_DB: MilitaryPerson[] = [
  { bm: "161.382-7", name: "Gabriel Souza Silva", rank: "Sd 1ª Classe", cpf: "12345678900" },
  { bm: "150.999-0", name: "João Pereira Santos", rank: "Sgt", cpf: "98765432100" },
  { bm: "140.111-2", name: "Ana Beatriz Oliveira", rank: "Ten", cpf: "11122233344" },
  { bm: "100.200-3", name: "Marcos Antonio Rocha", rank: "Cap", cpf: "55566677788" },
];

export const MATERIAL_TYPES = [
  MaterialType.TERRESTRE,
  MaterialType.INCENDIO,
  MaterialType.FLORESTAL,
  MaterialType.APH,
  MaterialType.AQUATICO,
  MaterialType.FERRAMENTAS
];

import { GoogleGenAI } from "@google/genai";
import { Movement } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getSmartSummary = async (movements: Movement[]) => {
  if (!process.env.API_KEY) return "Configuração de IA indisponível.";

  const pending = movements.filter(m => m.status === 'PENDENTE');
  const context = pending.map(m => `${m.name} (${m.rank}) - ${m.material} em ${m.dateCheckout}`).join('\n');

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analise a seguinte lista de materiais acautelados e forneça um resumo executivo rápido para a Seção de Apoio Operacional (SAO). Liste os itens mais críticos ou quem está com mais materiais pendentes de forma amigável e profissional.\n\n${context}`,
      config: {
        systemInstruction: "Você é o assistente inteligente da Seção de Apoio Operacional (SAO) do 6º Batalhão de Bombeiros Militar. Sua linguagem deve ser técnica, militar e prestativa.",
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar o resumo inteligente no momento.";
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { AuthState, MilitaryPerson, Movement, MovementStatus, MaterialType } from './types';
import { MOCK_MILITARY_DB, MATERIAL_TYPES } from './constants';
import { getSmartSummary } from './geminiService';
import { 
  ClipboardList, 
  LogIn, 
  LogOut, 
  History, 
  PlusCircle, 
  Search, 
  ShieldAlert,
  User,
  ArrowRightLeft,
  ChevronDown,
  CheckCircle2,
  AlertTriangle,
  Sparkles
} from 'lucide-react';

// --- Sub-components ---

const Header: React.FC<{ onLogout: () => void; user: MilitaryPerson | null }> = ({ onLogout, user }) => (
  <header className="bg-red-700 text-white shadow-lg p-4 sticky top-0 z-50">
    <div className="max-w-6xl mx-auto flex justify-between items-center">
      <div className="flex items-center gap-3">
        <div className="bg-white p-2 rounded-full">
          <ShieldAlert className="text-red-700 w-6 h-6" />
        </div>
        <div>
          <h1 className="font-bold text-lg leading-tight">6º BBM - SAO</h1>
          <p className="text-xs opacity-90 uppercase tracking-wider">Seção de Apoio Operacional</p>
        </div>
      </div>
      {user && (
        <div className="flex items-center gap-4">
          <div className="hidden sm:block text-right">
            <p className="text-sm font-semibold">{user.rank} {user.name.split(' ')[0]}</p>
            <p className="text-[10px] opacity-75">{user.bm}</p>
          </div>
          <button 
            onClick={onLogout}
            className="p-2 hover:bg-red-800 rounded-lg transition-colors"
            title="Sair"
          >
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      )}
    </div>
  </header>
);

const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form states
  const [loginBm, setLoginBm] = useState('');
  const [loginCpf, setLoginCpf] = useState('');
  const [visitorName, setVisitorName] = useState('');
  const [visitorBm, setVisitorBm] = useState('');
  const [visitorCpf, setVisitorCpf] = useState('');
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);

  // Load persistence (mocking database with localStorage)
  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const user = MOCK_MILITARY_DB.find(m => m.bm === loginBm && m.cpf === loginCpf);
    if (user) {
      setAuthState({ user, isVisitor: false });
    } else {
      alert("Credenciais inválidas. Verifique o BM e CPF.");
    }
  };

  const handleVisitorLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (visitorName && visitorBm && visitorCpf) {
      setAuthState({ 
        user: { name: visitorName, bm: visitorBm, rank: "VISITANTE", cpf: visitorCpf }, 
        isVisitor: true 
      });
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    setLoginBm('');
    setLoginCpf('');
    setAiSummary(null);
  };

  const handleCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authState.user) return;

    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm,
      name: authState.user.name,
      rank: authState.user.rank,
      dateCheckout: new Date().toLocaleString('pt-BR'),
      material: checkoutMaterial,
      type: checkoutType,
      status: MovementStatus.PENDENTE
    };

    setMovements([newMovement, ...movements]);
    setCheckoutMaterial('');
    alert("Material acautelado com sucesso!");
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;

    setMovements(movements.map(m => {
      if (m.id === id) {
        return {
          ...m,
          status: MovementStatus.DEVOLVIDO,
          dateReturn: new Date().toLocaleString('pt-BR'),
          observations: obs || 'Sem observações.',
          receiverBm: authState.user?.bm,
          receiverName: authState.user?.name
        };
      }
      return m;
    }));
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    return movements.filter(m => 
      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.material.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.bm.includes(searchTerm)
    );
  }, [movements, searchTerm]);

  // View: Login
  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-900 bg-opacity-95 bg-[url('https://picsum.photos/1600/900?grayscale')] bg-blend-multiply bg-cover">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden border border-slate-200">
          <div className="bg-red-700 p-8 text-center text-white">
            <ShieldAlert className="w-16 h-16 mx-auto mb-4" />
            <h1 className="text-2xl font-bold uppercase tracking-tight">SAO - 6º BBM</h1>
            <p className="text-sm opacity-80 mt-1">Controle de Materiais Operacionais</p>
          </div>

          <div className="p-8">
            {!authState.isVisitor ? (
              <form onSubmit={handleLogin} className="space-y-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Nº BM (Ex: 161.382-7)</label>
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="000.000-0"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                      value={loginBm}
                      onChange={(e) => setLoginBm(e.target.value)}
                      required
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Senha (CPF)</label>
                  <div className="relative">
                    <LogIn className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                    <input 
                      type="password" 
                      placeholder="Apenas números"
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                      value={loginCpf}
                      onChange={(e) => setLoginCpf(e.target.value)}
                      required
                    />
                  </div>
                </div>
                <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98]">
                  ENTRAR NO SISTEMA
                </button>
                <div className="relative py-2">
                  <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-slate-200"></span></div>
                  <div className="relative flex justify-center text-xs uppercase"><span className="bg-white px-2 text-slate-400 font-medium">Ou</span></div>
                </div>
                <button 
                  type="button" 
                  onClick={() => setAuthState({ ...authState, isVisitor: true })}
                  className="w-full bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold py-3 rounded-xl transition-all"
                >
                  ENTRAR COMO VISITANTE
                </button>
              </form>
            ) : (
              <form onSubmit={handleVisitorLogin} className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
                <h3 className="font-bold text-slate-800 text-center uppercase tracking-wider">Acesso Visitante</h3>
                <input 
                  type="text" 
                  placeholder="Nome Completo"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-red-500"
                  value={visitorName}
                  onChange={(e) => setVisitorName(e.target.value)}
                  required
                />
                <input 
                  type="text" 
                  placeholder="Nº BM (se houver) ou RG"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-red-500"
                  value={visitorBm}
                  onChange={(e) => setVisitorBm(e.target.value)}
                  required
                />
                <input 
                  type="password" 
                  placeholder="CPF"
                  className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-red-500"
                  value={visitorCpf}
                  onChange={(e) => setVisitorCpf(e.target.value)}
                  required
                />
                <div className="grid grid-cols-2 gap-3">
                   <button 
                    type="button" 
                    onClick={() => setAuthState({ ...authState, isVisitor: false })}
                    className="w-full bg-slate-100 hover:bg-slate-200 text-slate-600 font-bold py-3 rounded-xl transition-all"
                  >
                    VOLTAR
                  </button>
                  <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98]">
                    CONFIRMAR
                  </button>
                </div>
              </form>
            )}
          </div>
        </div>
        <p className="text-white text-[10px] mt-6 opacity-60 uppercase tracking-widest font-medium">© 2024 Corpo de Bombeiros Militar de Minas Gerais</p>
      </div>
    );
  }

  // View: Authenticated Dashboard
  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0">
      <Header onLogout={handleLogout} user={authState.user} />

      <main className="flex-1 max-w-6xl w-full mx-auto p-4 sm:p-6 lg:p-8 space-y-6">

        {/* Mobile-Friendly Tabs */}
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40">
          <button 
            onClick={() => setActiveTab('checkout')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkout' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <PlusCircle className="w-4 h-4" />
            <span className="text-xs sm:text-sm">ACAUTELAR</span>
          </button>
          <button 
            onClick={() => setActiveTab('checkin')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkin' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <ArrowRightLeft className="w-4 h-4" />
            <span className="text-xs sm:text-sm">DEVOLVER</span>
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'history' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <History className="w-4 h-4" />
            <span className="text-xs sm:text-sm">HISTÓRICO</span>
          </button>
        </div>

        {/* Tab Content */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-red-50 p-3 rounded-2xl text-red-600">
                  <ClipboardList className="w-6 h-6" />
                </div>
                <h2 className="text-xl font-bold text-slate-800">Acautelar Novo Material</h2>
              </div>

              <form onSubmit={handleCheckout} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Descrição do Material</label>
                    <textarea 
                      placeholder="Ex: 01 mangueira, 01 desencarcerador, 01 mochila..."
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl min-h-[120px] outline-none focus:ring-2 focus:ring-red-500 transition-all resize-none"
                      value={checkoutMaterial}
                      onChange={(e) => setCheckoutMaterial(e.target.value)}
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Tipo de Material</label>
                    <div className="grid grid-cols-1 gap-2">
                      {MATERIAL_TYPES.map((type) => (
                        <button
                          key={type}
                          type="button"
                          onClick={() => setCheckoutType(type)}
                          className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${checkoutType === type ? 'border-red-600 bg-red-50 text-red-700 font-bold ring-1 ring-red-600' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}
                        >
                          <span className="text-sm">{type}</span>
                          {checkoutType === type && <CheckCircle2 className="w-4 h-4" />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="p-4 bg-amber-50 rounded-2xl border border-amber-200 flex gap-3 text-amber-800 text-xs sm:text-sm">
                  <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                  <p>Certifique-se de conferir o estado físico de todos os materiais antes de confirmar o acautelamento.</p>
                </div>

                <button 
                  type="submit"
                  className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-2xl shadow-lg transition-all active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  CONFIRMAR ACAUTELAMENTO
                </button>
              </form>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="space-y-6">
              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center gap-3 mb-6">
                  <div className="bg-green-50 p-3 rounded-2xl text-green-600">
                    <ArrowRightLeft className="w-6 h-6" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">Devolução de Materiais</h2>
                </div>

                <div className="relative mb-6">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input 
                    type="text"
                    placeholder="Pesquisar por nome do militar, BM ou material..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-red-500 transition-all shadow-inner"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>

                <div className="space-y-4">
                  {movements.filter(m => m.status === MovementStatus.PENDENTE && (
                    m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    m.bm.includes(searchTerm) ||
                    m.material.toLowerCase().includes(searchTerm.toLowerCase())
                  )).length > 0 ? (
                    movements.filter(m => m.status === MovementStatus.PENDENTE && (
                      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                      m.bm.includes(searchTerm) ||
                      m.material.toLowerCase().includes(searchTerm.toLowerCase())
                    )).map((m) => (
                      <CheckinItem key={m.id} movement={m} onReturn={handleReturn} />
                    ))
                  ) : (
                    <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400">
                      <ClipboardList className="w-12 h-12 mx-auto mb-3 opacity-20" />
                      <p className="font-medium">Nenhum acautelamento pendente encontrado.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6">
              {/* Smart AI Section */}
              <div className="bg-gradient-to-br from-indigo-900 to-slate-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 -mr-20 -mt-20 rounded-full blur-3xl transition-all group-hover:scale-110"></div>
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 relative z-10">
                  <div className="flex items-center gap-3">
                    <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                      <Sparkles className="w-5 h-5 text-indigo-300" />
                    </div>
                    <div>
                      <h3 className="font-bold text-lg">Resumo Inteligente SAO</h3>
                      <p className="text-xs text-indigo-200">Análise automática de pendências via Gemini IA</p>
                    </div>
                  </div>
                  <button 
                    onClick={generateAiInsights}
                    disabled={isLoadingAi}
                    className="bg-white text-slate-900 px-6 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-50 transition-colors flex items-center gap-2 disabled:opacity-50"
                  >
                    {isLoadingAi ? 'Analisando...' : 'GERAR RELATÓRIO IA'}
                  </button>
                </div>
                {aiSummary && (
                  <div className="mt-6 p-5 bg-white/10 backdrop-blur-md rounded-2xl border border-white/10 text-sm leading-relaxed animate-in fade-in slide-in-from-top-2">
                    {aiSummary}
                  </div>
                )}
              </div>

              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="bg-slate-50 p-3 rounded-2xl text-slate-600">
                      <History className="w-6 h-6" />
                    </div>
                    <h2 className="text-xl font-bold text-slate-800">Histórico de Movimentações</h2>
                  </div>
                  <div className="text-xs font-bold text-slate-400 uppercase">
                    Total: {movements.length} registros
                  </div>
                </div>

                <div className="relative mb-6">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input 
                    type="text"
                    placeholder="Filtrar histórico..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-slate-300 transition-all shadow-inner"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Data</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Militar</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Material</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Status</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Devolução</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredMovements.map((m) => (
                        <tr key={m.id} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 px-2">
                            <p className="text-sm font-medium text-slate-700">{m.dateCheckout.split(',')[0]}</p>
                            <p className="text-[10px] text-slate-400">{m.dateCheckout.split(',')[1]}</p>
                          </td>
