        <button onClick={() => setActiveTab('checkout')} className={`flex flex-col items-center ${activeTab === 'checkout' ? 'text-red-700' : 'text-slate-400'}`}>
          <PlusCircle className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Acautelar</span>
        </button>
        <button onClick={() => setActiveTab('checkin')} className={`flex flex-col items-center ${activeTab === 'checkin' ? 'text-red-700' : 'text-slate-400'}`}>
          <ArrowRightLeft className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Devolver</span>
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center ${activeTab === 'history' ? 'text-red-700' : 'text-slate-400'}`}>
          <History className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Histórico</span>
        </button>
        <button onClick={handleLogout} className="flex flex-col items-center text-slate-400">
          <LogOut className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Sair</span>
        </button>
      </footer>
    </div>
  );
};

