const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form states for Identification
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  // Checkout states
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);

  // Load persistence
  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));

    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const user: MilitaryPerson = { 
        rank: formRank, 
        name: formName, 
        bm: formBm,
        cpf: '' // CPF removed as per request to focus on identifying fields
      };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else {
      alert("Por favor, preencha todos os campos de identificação.");
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName('');
    setFormBm('');
    setAiSummary(null);
  };

  const handleCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authState.user) return;

    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm,
      name: authState.user.name,
      rank: authState.user.rank,
      dateCheckout: new Date().toLocaleString('pt-BR'),
      material: checkoutMaterial,
      type: checkoutType,
      status: MovementStatus.PENDENTE
    };

    setMovements([newMovement, ...movements]);
    setCheckoutMaterial('');
    alert("Material acautelado com sucesso!");
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;

    setMovements(movements.map(m => {
      if (m.id === id) {
        return {
          ...m,
          status: MovementStatus.DEVOLVIDO,
          dateReturn: new Date().toLocaleString('pt-BR'),
          observations: obs || 'Sem observações.',
          receiverBm: authState.user?.bm,
          receiverName: authState.user?.name
        };
      }
      return m;
    }));
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    return movements.filter(m => 
      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.material.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.bm.includes(searchTerm)
    );
  }, [movements, searchTerm]);

  // View: Identification (Replacing Login)
  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-900 bg-opacity-95 bg-[url('https://picsum.photos/1600/900?grayscale')] bg-blend-multiply bg-cover">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden border border-slate-200">
          <div className="bg-red-700 p-8 text-center text-white">
            <ShieldAlert className="w-16 h-16 mx-auto mb-4" />
            <h1 className="text-2xl font-bold uppercase tracking-tight">SAO - 6º BBM</h1>
            <p className="text-sm opacity-80 mt-1">Identificação para Acesso</p>
          </div>

          <div className="p-8">
            <form onSubmit={handleIdentify} className="space-y-4">
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Posto e Graduação</label>
                <div className="relative">
                  <select 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all appearance-none text-slate-700"
                    value={formRank}
                    onChange={(e) => setFormRank(e.target.value)}
                    required
                  >
                    <option value="">Selecione...</option>
                    {RANKS.map(rank => (
                      <option key={rank} value={rank}>{rank}</option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Nome Completo</label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Ex: João da Silva"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                    value={formName}
                    onChange={(e) => setFormName(e.target.value)}
                    required
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Número BM</label>
                <div className="relative">
                  <IdCard className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Ex: 161.382-7"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                    value={formBm}
                    onChange={(e) => setFormBm(e.target.value)}
                    required
                  />
                </div>
              </div>

              <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-[0.98] mt-4 uppercase tracking-wider">
                Acessar Sistema
              </button>
            </form>
          </div>
        </div>
        <p className="text-white text-[10px] mt-6 opacity-60 uppercase tracking-widest font-medium">© 2024 Corpo de Bombeiros Militar de Minas Gerais</p>
      </div>
    );
  }

  // View: Authenticated Dashboard (The rest remains identical as it already supported dynamic user data)
  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0">
      <Header onLogout={handleLogout} user={authState.user} />

      <main className="flex-1 max-w-6xl w-full mx-auto p-4 sm:p-6 lg:p-8 space-y-6">

        {/* Mobile-Friendly Tabs */}
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40">
          <button 
            onClick={() => setActiveTab('checkout')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkout' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <PlusCircle className="w-4 h-4" />
            <span className="text-xs sm:text-sm">ACAUTELAR</span>
          </button>
          <button 
            onClick={() => setActiveTab('checkin')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkin' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <ArrowRightLeft className="w-4 h-4" />
            <span className="text-xs sm:text-sm">DEVOLVER</span>
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'history' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <History className="w-4 h-4" />
            <span className="text-xs sm:text-sm">HISTÓRICO</span>
          </button>
        </div>

        {/* Tab Content */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-red-50 p-3 rounded-2xl text-red-600">
                  <ClipboardList className="w-6 h-6" />
                </div>
                <h2 className="text-xl font-bold text-slate-800">Acautelar Novo Material</h2>
              </div>

              <form onSubmit={handleCheckout} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
