                    onClick={generateAiInsights}
                    disabled={isLoadingAi}
                    className="bg-white text-slate-900 px-6 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-50 transition-colors flex items-center gap-2 disabled:opacity-50"
                  >
                    {isLoadingAi ? 'Analisando...' : 'GERAR RELATÓRIO IA'}
                  </button>
                </div>
                {aiSummary && (
                  <div className="mt-6 p-5 bg-white/10 backdrop-blur-md rounded-2xl border border-white/10 text-sm leading-relaxed animate-in fade-in slide-in-from-top-2">
                    {aiSummary}
                  </div>
                )}
              </div>

              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="bg-slate-50 p-3 rounded-2xl text-slate-600">
                      <History className="w-6 h-6" />
                    </div>
                    <h2 className="text-xl font-bold text-slate-800">Histórico de Movimentações</h2>
                  </div>
                  <div className="text-xs font-bold text-slate-400 uppercase">
                    Total: {movements.length} registros
                  </div>
                </div>

                <div className="relative mb-6">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input 
                    type="text"
                    placeholder="Filtrar histórico..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-slate-300 transition-all shadow-inner"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead>
                      <tr className="border-b border-slate-100">
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Data</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Militar</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Material</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Status</th>
                        <th className="pb-4 text-xs font-bold text-slate-400 uppercase px-2">Devolução</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredMovements.map((m) => (
                        <tr key={m.id} className="hover:bg-slate-50 transition-colors">
                          <td className="py-4 px-2">
                            <p className="text-sm font-medium text-slate-700">{m.dateCheckout.split(',')[0]}</p>
                            <p className="text-[10px] text-slate-400">{m.dateCheckout.split(',')[1]}</p>
                          </td>
                          <td className="py-4 px-2">
                            <p className="text-sm font-bold text-slate-800">{m.rank} {m.name.split(' ')[0]}</p>
                            <p className="text-[10px] text-slate-500">{m.bm}</p>
                          </td>
                          <td className="py-4 px-2">
                            <p className="text-sm text-slate-600 line-clamp-1">{m.material}</p>
                            <p className="text-[10px] text-red-500 font-semibold uppercase">{m.type}</p>
                          </td>
                          <td className="py-4 px-2">
                            <span className={`inline-flex px-2 py-1 rounded-full text-[10px] font-bold ${m.status === MovementStatus.PENDENTE ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'}`}>
                              {m.status}
                            </span>
                          </td>
                          <td className="py-4 px-2">
                            {m.dateReturn ? (
                              <div>
                                <p className="text-sm text-slate-700">{m.dateReturn.split(',')[0]}</p>
                                <p className="text-[10px] text-slate-400">Rec: {m.receiverName?.split(' ')[0]}</p>
                              </div>
                            ) : (
                              <p className="text-sm text-slate-300 italic">Pendente</p>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {/* Persistent Menu (Bottom) */}
      <footer className="sm:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-6 py-3 flex justify-between items-center z-50">
        <button onClick={() => setActiveTab('checkout')} className={`flex flex-col items-center ${activeTab === 'checkout' ? 'text-red-700' : 'text-slate-400'}`}>
          <PlusCircle className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Acautelar</span>
        </button>
        <button onClick={() => setActiveTab('checkin')} className={`flex flex-col items-center ${activeTab === 'checkin' ? 'text-red-700' : 'text-slate-400'}`}>
          <ArrowRightLeft className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Devolver</span>
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center ${activeTab === 'history' ? 'text-red-700' : 'text-slate-400'}`}>
          <History className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Histórico</span>
        </button>
        <button onClick={handleLogout} className="flex flex-col items-center text-slate-400">
          <LogOut className="w-6 h-6" />
          <span className="text-[10px] font-bold mt-1 uppercase">Trocar</span>
        </button>
      </footer>
    </div>
  );
};

// Sub-component for individual checkin items
