        >
          {showForm ? 'CANCELAR' : 'REGISTRAR DEVOLUÇÃO'}
        </button>
      </div>

      {showForm && (
        <div className="px-4 pb-4 bg-slate-50 border-t border-slate-100 animate-in slide-in-from-top-2">
          <div className="pt-4 space-y-3">
            <label className="text-[10px] font-bold text-slate-500 uppercase">Observações (Avarias, devolução parcial, etc.)</label>
            <textarea 
              className="w-full p-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-green-500"
              placeholder="Descreva se o material está avariado ou se a devolução é parcial..."
              value={obs}
              onChange={(e) => setObs(e.target.value)}
            />
            <div className="flex justify-end">
              <button 
                onClick={() => {
                  onReturn(movement.id, obs);
                  setShowForm(false);
                  alert("Devolução processada com sucesso!");
                }}
                className="bg-green-700 text-white px-8 py-2 rounded-xl text-xs font-bold hover:bg-green-800 transition-colors shadow-lg"
              >
                CONFIRMAR RECEBIMENTO
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum MaterialType {
  TERRESTRE = "Salv. Terrestre/Altura",
  INCENDIO = "Incêndio Urbano",
  FLORESTAL = "Florestal",
  APH = "APH",
  AQUATICO = "Salv. Aquático",
  FERRAMENTAS = "Ferramentas diversas",
  OUTROS = "Outros"
}

export enum MovementStatus {
  PENDENTE = "PENDENTE",
  DEVOLVIDO = "DEVOLVIDO"
}

export interface MilitaryPerson {
  bm: string;
  name: string;
  rank: string;
  cpf: string;
}

export interface Movement {
  id: string;
  bm: string;
  name: string;
  rank: string;
  dateCheckout: string;
  estimatedReturnDate?: string;
  material: string;
  type: MaterialType;
  status: MovementStatus;
  dateReturn?: string;
  observations?: string;
  receiverBm?: string;
  receiverName?: string;
}

export interface AuthState {
  user: MilitaryPerson | null;
  isVisitor: boolean;
}

import React, { useState, useEffect, useMemo } from 'react';
import { AuthState, MilitaryPerson, Movement, MovementStatus, MaterialType } from './types';
import { MATERIAL_TYPES, RANKS } from './constants';
import { getSmartSummary } from './geminiService';
import { 
  ClipboardList, 
  LogOut, 
  History, 
  PlusCircle, 
  Search, 
  ShieldAlert,
  User,
  ArrowRightLeft,
  CheckCircle2,
  AlertTriangle,
  Sparkles,
  IdCard,
  ChevronDown,
  Calendar
} from 'lucide-react';

// --- Sub-components ---

const Header: React.FC<{ onLogout: () => void; user: MilitaryPerson | null }> = ({ onLogout, user }) => (
  <header className="bg-red-700 text-white shadow-lg p-4 sticky top-0 z-50">
    <div className="max-w-6xl mx-auto flex justify-between items-center">
      <div className="flex items-center gap-3">
        <div className="bg-white p-2 rounded-full">
          <ShieldAlert className="text-red-700 w-6 h-6" />
        </div>
        <div>
          <h1 className="font-bold text-lg leading-tight">6º BBM - SAO</h1>
          <p className="text-xs opacity-90 uppercase tracking-wider">Seção de Apoio Operacional</p>
        </div>
      </div>
      {user && (
        <div className="flex items-center gap-4">
          <div className="hidden sm:block text-right">
            <p className="text-sm font-semibold">{user.rank} {user.name.split(' ')[0]}</p>
            <p className="text-[10px] opacity-75">{user.bm}</p>
          </div>
          <button 
            onClick={onLogout}
            className="p-2 hover:bg-red-800 rounded-lg transition-colors"
            title="Sair / Trocar Usuário"
          >
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      )}
    </div>
  </header>
);

const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form states for Identification
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  // Checkout states
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState('');

  // Load persistence
  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));

    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const user: MilitaryPerson = { 
        rank: formRank, 
        name: formName, 
        bm: formBm,
        cpf: '' 
      };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else {
      alert("Por favor, preencha todos os campos de identificação.");
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName('');
    setFormBm('');
    setAiSummary(null);
  };

  const handleCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!authState.user) return;

    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm,
      name: authState.user.name,
      rank: authState.user.rank,
      dateCheckout: new Date().toLocaleString('pt-BR'),
      estimatedReturnDate: checkoutEstimatedReturn,
      material: checkoutMaterial,
      type: checkoutType,
      status: MovementStatus.PENDENTE
    };

    setMovements([newMovement, ...movements]);
    setCheckoutMaterial('');
    setCheckoutEstimatedReturn('');
    alert("Material acautelado com sucesso!");
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;

    setMovements(movements.map(m => {
      if (m.id === id) {
        return {
          ...m,
          status: MovementStatus.DEVOLVIDO,
          dateReturn: new Date().toLocaleString('pt-BR'),
          observations: obs || 'Sem observações.',
          receiverBm: authState.user?.bm,
          receiverName: authState.user?.name
        };
      }
      return m;
    }));
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    return movements.filter(m => 
      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.material.toLowerCase().includes(searchTerm.toLowerCase()) ||
      m.bm.includes(searchTerm)
    );
  }, [movements, searchTerm]);

  const isOverdue = (dateStr?: string) => {
    if (!dateStr) return false;
    const estimated = new Date(dateStr);
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    estimated.setHours(0, 0, 0, 0);
    return estimated < now;
  };

  // View: Identification
  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-900 bg-opacity-95 bg-[url('https://picsum.photos/1600/900?grayscale')] bg-blend-multiply bg-cover">
        <div className="w-full max-w-md bg-white rounded-2xl shadow-2xl overflow-hidden border border-slate-200">
          <div className="bg-red-700 p-8 text-center text-white">
            <ShieldAlert className="w-16 h-16 mx-auto mb-4" />
            <h1 className="text-2xl font-bold uppercase tracking-tight">SAO - 6º BBM</h1>
            <p className="text-sm opacity-80 mt-1">Identificação para Acesso</p>
          </div>

          <div className="p-8">
            <form onSubmit={handleIdentify} className="space-y-4">
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Posto e Graduação</label>
                <div className="relative">
                  <select 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all appearance-none text-slate-700"
                    value={formRank}
                    onChange={(e) => setFormRank(e.target.value)}
                    required
                  >
                    <option value="">Selecione...</option>
                    {RANKS.map(rank => (
                      <option key={rank} value={rank}>{rank}</option>
                    ))}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Nome Completo</label>
                <div className="relative">
                  <User className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Ex: João da Silva"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                    value={formName}
                    onChange={(e) => setFormName(e.target.value)}
                    required
                  />
                </div>
              </div>

              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Número BM</label>
                <div className="relative">
                  <IdCard className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder="Ex: 161.382-7"
                    className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-transparent outline-none transition-all"
                    value={formBm}
                    onChange={(e) => setFormBm(e.target.value)}
                    required
                  />
                </div>
              </div>

              <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-[0.98] mt-4 uppercase tracking-wider">
                Acessar Sistema
              </button>
            </form>
          </div>
        </div>
        <p className="text-white text-[10px] mt-6 opacity-60 uppercase tracking-widest font-medium">© 2024 Corpo de Bombeiros Militar de Minas Gerais</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0">
      <Header onLogout={handleLogout} user={authState.user} />

      <main className="flex-1 max-w-6xl w-full mx-auto p-4 sm:p-6 lg:p-8 space-y-6">

        {/* Mobile-Friendly Tabs */}
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40">
          <button 
            onClick={() => setActiveTab('checkout')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkout' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <PlusCircle className="w-4 h-4" />
            <span className="text-xs sm:text-sm">ACAUTELAR</span>
          </button>
          <button 
            onClick={() => setActiveTab('checkin')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkin' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <ArrowRightLeft className="w-4 h-4" />
            <span className="text-xs sm:text-sm">DEVOLVER</span>
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'history' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <History className="w-4 h-4" />
            <span className="text-xs sm:text-sm">HISTÓRICO</span>
          </button>
        </div>

        {/* Tab Content */}
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-red-50 p-3 rounded-2xl text-red-600">
                  <ClipboardList className="w-6 h-6" />
                </div>
                <h2 className="text-xl font-bold text-slate-800">Acautelar Novo Material</h2>
              </div>

              <form onSubmit={handleCheckout} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Descrição do Material</label>
                      <textarea 
                        placeholder="Ex: 01 mangueira, 01 desencarcerador, 01 mochila..."
                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl min-h-[120px] outline-none focus:ring-2 focus:ring-red-500 transition-all resize-none"
                        value={checkoutMaterial}
                        onChange={(e) => setCheckoutMaterial(e.target.value)}
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Previsão de Entrega</label>
                      <div className="relative">
                        <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                        <input 
                          type="date"
                          className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-red-500 outline-none"
                          value={checkoutEstimatedReturn}
                          onChange={(e) => setCheckoutEstimatedReturn(e.target.value)}
                          required
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Tipo de Material</label>
                    <div className="grid grid-cols-1 gap-2">
                      {MATERIAL_TYPES.map((type) => (
                        <button
                          key={type}
                          type="button"
                          onClick={() => setCheckoutType(type)}
                          className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${checkoutType === type ? 'border-red-600 bg-red-50 text-red-700 font-bold ring-1 ring-red-600' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}
                        >
                          <span className="text-sm">{type}</span>
                          {checkoutType === type && <CheckCircle2 className="w-4 h-4" />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="p-4 bg-amber-50 rounded-2xl border border-amber-200 flex gap-3 text-amber-800 text-xs sm:text-sm">
                  <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                  <p>Certifique-se de conferir o estado físico de todos os materiais antes de confirmar o acautelamento.</p>
                </div>

                <button 
                  type="submit"
                  className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-2xl shadow-lg transition-all active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  CONFIRMAR ACAUTELAMENTO
                </button>
              </form>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="space-y-6">
              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center gap-3 mb-6">
                  <div className="bg-green-50 p-3 rounded-2xl text-green-600">
                    <ArrowRightLeft className="w-6 h-6" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">Devolução de Materiais</h2>
                </div>

                <div className="relative mb-6">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input 
