          <button 
            onClick={() => setActiveTab('checkout')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkout' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <PlusCircle className="w-4 h-4" />
            <span className="text-xs sm:text-sm">ACAUTELAR</span>
          </button>
          <button 
            onClick={() => setActiveTab('checkin')}
            className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold transition-all ${activeTab === 'checkin' ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <ArrowRightLeft className="w-4 h-4" />
            <span className="text-xs sm:text-sm">DEVOLVER</span>
          </button>
          <button 
