                      <p className="text-[10px] text-slate-400 italic ml-1">Clique para selecionar a data no calendário</p>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Tipo de Material</label>
                    <div className="grid grid-cols-1 gap-2">
                      {MATERIAL_TYPES.map((type) => (
                        <button
                          key={type}
