                          onClick={() => setCheckoutType(type)}
                          className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${checkoutType === type ? 'border-red-600 bg-red-50 text-red-700 font-bold ring-1 ring-red-600' : 'border-slate-200 bg-white text-slate-600 hover:border-slate-300'}`}
                        >
                          <span className="text-sm">{type}</span>
                          {checkoutType === type && <CheckCircle2 className="w-4 h-4" />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>

                <div className="p-4 bg-amber-50 rounded-2xl border border-amber-200 flex gap-3 text-amber-800 text-xs sm:text-sm">
                  <AlertTriangle className="w-5 h-5 flex-shrink-0" />
                  <p>Certifique-se de conferir o estado físico de todos os materiais antes de confirmar o acautelamento.</p>
                </div>

                <button 
                  type="submit"
                  className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-2xl shadow-lg transition-all active:scale-[0.98] flex items-center justify-center gap-2"
                >
                  CONFIRMAR ACAUTELAMENTO
                </button>
              </form>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="space-y-6">
              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center gap-3 mb-6">
                  <div className="bg-green-50 p-3 rounded-2xl text-green-600">
                    <ArrowRightLeft className="w-6 h-6" />
                  </div>
                  <h2 className="text-xl font-bold text-slate-800">Devolução de Materiais</h2>
                </div>

                <div className="relative mb-6">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                  <input 
                    type="text"
                    placeholder="Pesquisar por nome do militar, BM ou material..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-red-500 transition-all shadow-inner"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>

                <div className="space-y-4">
                  {movements.filter(m => m.status === MovementStatus.PENDENTE && (
                    m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    m.warName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                    m.bm.includes(searchTerm) ||
                    m.material.toLowerCase().includes(searchTerm.toLowerCase())
                  )).length > 0 ? (
                    movements.filter(m => m.status === MovementStatus.PENDENTE && (
                      m.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                      m.warName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                      m.bm.includes(searchTerm) ||
                      m.material.toLowerCase().includes(searchTerm.toLowerCase())
                    )).map((m) => (
                      <CheckinItem key={m.id} movement={m} onReturn={handleReturn} overdue={isOverdue(m.estimatedReturnDate)} />
                    ))
                  ) : (
                    <div className="text-center py-12 border-2 border-dashed border-slate-200 rounded-3xl text-slate-400">
                      <ClipboardList className="w-12 h-12 mx-auto mb-3 opacity-20" />
                      <p className="font-medium">Nenhum acautelamento pendente encontrado.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6">
              {/* Smart AI Section */}
              <div className="bg-gradient-to-br from-indigo-900 to-slate-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 -mr-20 -mt-20 rounded-full blur-3xl transition-all group-hover:scale-110"></div>
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 relative z-10">
                  <div className="flex items-center gap-3">
                    <div className="bg-white/20 p-2 rounded-xl backdrop-blur-sm">
                      <Sparkles className="w-5 h-5 text-indigo-300" />
                    </div>
                    <div>
                      <h3 className="font-bold text-lg">Resumo Inteligente SAO</h3>
                      <p className="text-xs text-indigo-200">Análise automática de pendências via Gemini IA</p>
                    </div>
                  </div>
                  <button 
                    onClick={generateAiInsights}
                    disabled={isLoadingAi}
                    className="bg-white text-slate-900 px-6 py-2.5 rounded-xl text-xs font-bold hover:bg-indigo-50 transition-colors flex items-center gap-2 disabled:opacity-50"
                  >
                    {isLoadingAi ? 'Analisando...' : 'GERAR RELATÓRIO IA'}
                  </button>
                </div>
                {aiSummary && (
                  <div className="mt-6 p-5 bg-white/10 backdrop-blur-md rounded-2xl border border-white/10 text-sm leading-relaxed animate-in fade-in slide-in-from-top-2">
                    {aiSummary}
                  </div>
                )}
              </div>

              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex items-center justify-between mb-6">
                  <div className="flex items-center gap-3">
                    <div className="bg-slate-50 p-3 rounded-2xl text-slate-600">
                      <History className="w-6 h-6" />
                    </div>
                    <h2 className="text-xl font-bold text-slate-800">Histórico de Movimentações</h2>
                  </div>
                  <div className="text-xs font-bold text-slate-400 uppercase">
