                    type="text"
                    placeholder="Filtrar histórico..."
                    className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-slate-300 transition-all shadow-inner"
