                            <td className="py-4 px-2">
                              <p className="text-sm text-slate-600 line-clamp-1">{m.material}</p>
                              <p className="text-[10px] text-red-500 font-semibold uppercase">{m.type}</p>
                            </td>
                            <td className="py-4 px-2">
                              <div className="flex flex-col gap-1 items-start">
                                <span className={`inline-flex px-2 py-1 rounded-full text-[10px] font-bold ${m.status === MovementStatus.PENDENTE ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'}`}>
