};

// Sub-component for individual checkin items
const CheckinItem: React.FC<{ 
  movement: Movement; 
  onReturn: (id: string, obs: string) => void;
  overdue: boolean;
}> = ({ movement, onReturn, overdue }) => {
  const [showForm, setShowForm] = useState(false);
  const [obs, setObs] = useState('');

  return (
    <div className={`bg-white border rounded-2xl overflow-hidden hover:shadow-md transition-all ${overdue ? 'border-red-300 shadow-sm' : 'border-slate-200'}`}>
      <div className="p-4 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-1">
             <span className="px-2 py-0.5 bg-red-100 text-red-700 text-[10px] font-bold rounded uppercase">{movement.type}</span>
             <span className="text-xs text-slate-400 font-medium">Acautelado em: {movement.dateCheckout}</span>
             {movement.estimatedReturnDate && (
               <span className={`text-[10px] font-bold ${overdue ? 'text-red-600 animate-pulse' : 'text-slate-500'}`}>
                 Previsto: {new Date(movement.estimatedReturnDate).toLocaleDateString('pt-BR')}
               </span>
             )}
          </div>
          <h4 className="font-bold text-slate-800">{movement.rank} {movement.warName}</h4>
          <p className="text-sm text-slate-600 mt-1 italic">"{movement.material}"</p>
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          className={`${overdue ? 'bg-red-600 hover:bg-red-700' : 'bg-green-600 hover:bg-green-700'} text-white font-bold px-6 py-2 rounded-xl text-xs sm:text-sm transition-all shadow-sm flex items-center gap-2`}
        >
          {showForm ? 'CANCELAR' : 'REGISTRAR DEVOLUÇÃO'}
        </button>
      </div>

      {showForm && (
        <div className="px-4 pb-4 bg-slate-50 border-t border-slate-100 animate-in slide-in-from-top-2">
          <div className="pt-4 space-y-3">
            <label className="text-[10px] font-bold text-slate-500 uppercase">Observações (Avarias, devolução parcial, etc.)</label>
            <textarea 
              className="w-full p-3 bg-white border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-green-500"
              placeholder="Descreva se o material está avariado ou se a devolução é parcial..."
              value={obs}
              onChange={(e) => setObs(e.target.value)}
            />
            <div className="flex justify-end">
              <button 
                onClick={() => {
                  onReturn(movement.id, obs);
                  setShowForm(false);
                  alert("Devolução processada com sucesso!");
                }}
                className="bg-green-700 text-white px-8 py-2 rounded-xl text-xs font-bold hover:bg-green-800 transition-colors shadow-lg"
              >
                CONFIRMAR RECEBIMENTO
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

