import { GoogleGenAI } from "@google/genai";
import { Movement } from "./types";

// Always use the recommended initialization with named parameters.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getSmartSummary = async (movements: Movement[]) => {
  const pending = movements.filter(m => m.status === 'PENDENTE');
  const context = pending.map(m => `${m.name} (${m.rank}) - ${m.material} em ${m.dateCheckout}`).join('\n');

  try {
    // Calling generateContent with the model name and prompt directly.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analise a seguinte lista de materiais acautelados e forneça um resumo executivo rápido para a Seção de Apoio Operacional (SAO). Liste os itens mais críticos ou quem está com mais materiais pendentes de forma amigável e profissional.\n\n${context}`,
      config: {
        systemInstruction: "Você é o assistente inteligente da Seção de Apoio Operacional (SAO) do 6º Batalhão de Bombeiros Militar. Sua linguagem deve ser técnica, militar e prestativa.",
      }
    });
    // Correctly extracting text using the .text property (not a method).
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar o resumo inteligente no momento.";
  }
};

