// --- Helper Functions ---

const extractWarName = (fullName: string): string => {
  const matches = fullName.match(/\b[A-ZÁÉÍÓÚÀÈÌÒÙÂÊÎÔÛÃÕÇ]{2,}\b/g);
  if (matches && matches.length > 0) {
    return matches.join(' ');
  }
  return fullName.split(' ')[0];
};

const formatBM = (value: string): string => {
  const digits = value.replace(/\D/g, '').slice(0, 7);
  let formatted = digits;
  if (digits.length > 3 && digits.length <= 6) {
    formatted = `${digits.slice(0, 3)}.${digits.slice(3)}`;
  } else if (digits.length > 6) {
    formatted = `${digits.slice(0, 3)}.${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return formatted;
};

const formatDate = (dateStr?: string) => {
  if (!dateStr) return "-";
  try {
    const normalizedDate = dateStr.includes('T') ? dateStr : `${dateStr}T12:00:00`;
    const d = new Date(normalizedDate);
    if (isNaN(d.getTime())) return dateStr;
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    }).format(d);
  } catch {
    return dateStr;
  }
};

const formatDateTime = (dateStr?: string) => {
  if (!dateStr) return "-";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return new Intl.DateTimeFormat('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(d);
  } catch {
    return dateStr;
  }
};

