import { GoogleGenAI, Type } from "@google/genai";
import { Movement } from "./types";

export const getSmartSummary = async (movements: Movement[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const pending = movements.filter(m => m.status === 'PENDENTE');
  const context = pending.map(m => `${m.name} (${m.rank}) - ${m.material} em ${m.dateCheckout}`).join('\n');

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analise a seguinte lista de materiais acautelados e forneça um resumo executivo rápido para a Seção de Apoio Operacional (SAO). Liste os itens mais críticos ou quem está com mais materiais pendentes de forma amigável e profissional.\n\n${context}`,
      config: {
        systemInstruction: "Você é o assistente inteligente da Seção de Apoio Operacional (SAO) do 6º Batalhão de Bombeiros Militar. Sua linguagem deve ser técnica, militar e prestativa.",
      }
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Não foi possível gerar o resumo inteligente no momento.";
  }
};

export const generateAIImage = async (prompt: string, size: "1K" | "2K" | "4K") => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        imageConfig: {
          aspectRatio: "1:1",
          imageSize: size
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Image Gen Error:", error);
    throw error;
  }
};

export const editAIImage = async (base64Image: string, prompt: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image.split(',')[1],
              mimeType: 'image/png',
            },
          },
          { text: prompt },
        ],
      },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return null;
  } catch (error) {
    console.error("Image Edit Error:", error);
    throw error;
  }
};

