const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form State
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  // Checkout State
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState('');
  const [showCheckoutConfirm, setShowCheckoutConfirm] = useState(false);
  const dateInputRef = useRef<HTMLInputElement>(null);

  const todayStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));
    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const warName = extractWarName(formName);
      const user: MilitaryPerson = { rank: formRank, name: formName, warName: warName, bm: formBm, cpf: '' };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else {
      alert("Por favor, preencha todos os campos de identificação.");
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName(''); setFormBm(''); setAiSummary(null);
  };

  const initiateCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    setShowCheckoutConfirm(true);
  };

  const handleCheckoutFinal = () => {
    if (!authState.user) return;
    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm, name: authState.user.name, warName: authState.user.warName,
      rank: authState.user.rank, dateCheckout: new Date().toISOString(),
      estimatedReturnDate: checkoutEstimatedReturn, material: checkoutMaterial,
      type: checkoutType, status: MovementStatus.PENDENTE
    };
    setMovements([newMovement, ...movements]);
    setCheckoutMaterial(''); setCheckoutEstimatedReturn('');
    setShowCheckoutConfirm(false);
    alert("Material acautelado com sucesso!");
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;
    setMovements(movements.map(m => {
      if (m.id === id) {
        return {
          ...m, status: MovementStatus.DEVOLVIDO, dateReturn: new Date().toISOString(),
          observations: obs || 'Sem observações.', receiverBm: authState.user?.bm,
          receiverName: authState.user?.name, receiverWarName: authState.user?.warName,
          receiverRank: authState.user?.rank
        };
      }
      return m;
    }));
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return movements.filter(m => {
      const searchFields = [m.name, m.warName, m.material, m.bm, m.type, m.rank, m.status];
      return searchFields.some(field => field.toLowerCase().includes(term));
    });
