  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form State
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  // Checkout State
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState('');
  const [showCheckoutConfirm, setShowCheckoutConfirm] = useState(false);

  const todayStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));
    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const warName = extractWarName(formName);
      const user: MilitaryPerson = { rank: formRank, name: formName, warName: warName, bm: formBm, cpf: '' };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else {
      alert("Por favor, preencha todos os campos de identificação.");
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName(''); setFormBm(''); setAiSummary(null);
  };

  const initiateCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    setShowCheckoutConfirm(true);
  };

  const handleCheckoutFinal = () => {
    if (!authState.user) return;
    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm, name: authState.user.name, warName: authState.user.warName,
      rank: authState.user.rank, dateCheckout: new Date().toISOString(),
      estimatedReturnDate: checkoutEstimatedReturn, material: checkoutMaterial,
      type: checkoutType, status: MovementStatus.PENDENTE
    };
    setMovements([newMovement, ...movements]);
    setCheckoutMaterial(''); setCheckoutEstimatedReturn('');
    setShowCheckoutConfirm(false);
    alert("Material acautelado com sucesso!");
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;
    setMovements(movements.map(m => {
      if (m.id === id) {
        return {
          ...m, status: MovementStatus.DEVOLVIDO, dateReturn: new Date().toISOString(),
          observations: obs || 'Sem observações.', receiverBm: authState.user?.bm,
          receiverName: authState.user?.name, receiverWarName: authState.user?.warName,
          receiverRank: authState.user?.rank
        };
      }
      return m;
    }));
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return movements.filter(m => {
      const matchesStatus = statusFilter === 'all' || m.status === statusFilter;
      const checkoutDateStr = formatDate(m.dateCheckout);
      const returnDateStr = m.dateReturn ? formatDateTime(m.dateReturn) : "";

      const searchFields = [
        m.name, 
        m.warName, 
        m.material, 
        m.bm, 
        m.type, 
        m.rank, 
        m.status,
        checkoutDateStr,
        returnDateStr,
        m.receiverName || "",
        m.receiverWarName || ""
      ];

      const matchesSearch = searchFields.some(field => field.toLowerCase().includes(term));

      return matchesStatus && matchesSearch;
    });
  }, [movements, searchTerm, statusFilter]);

  const isOverdue = (dateStr?: string) => {
    if (!dateStr) return false;
    return new Date(`${dateStr}T23:59:59`) < new Date();
  };

  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-900 bg-opacity-95 bg-[url('https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?q=80&w=1600&auto=format&fit=crop')] bg-blend-multiply bg-cover">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
          <div className="bg-red-700 p-10 text-center text-white relative">
            <div className="absolute top-0 left-0 w-full h-1 bg-yellow-500"></div>
            <div className="mb-6">
              <h1 className="text-4xl font-black uppercase tracking-tighter leading-none">SAO - 6º BBM</h1>
              <p className="text-[10px] font-bold mt-2 opacity-80 tracking-widest">CONTROLE DE MATERIAL</p>
            </div>
          </div>
          <div className="p-8">
            <form onSubmit={handleIdentify} className="space-y-4">
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Posto/Graduação</label>
                <div className="relative">
                  <select className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl appearance-none font-medium outline-none focus:ring-2 focus:ring-red-500" value={formRank} onChange={(e) => setFormRank(e.target.value)} required>
                    <option value="">Selecione...</option>
                    {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Nome Completo</label>
                <input type="text" placeholder="Ex: JOÃO Augusto Fernandes" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500" value={formName} onChange={(e) => setFormName(e.target.value)} required />
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Número BM</label>
                <input type="text" placeholder="Ex: 123.345-6" maxLength={10} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold tracking-widest outline-none focus:ring-2 focus:ring-red-500" value={formBm} onChange={(e) => setFormBm(formatBM(e.target.value))} required />
              </div>
              <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-xl shadow-lg mt-4 uppercase tracking-widest text-sm border-b-4 border-red-900">Acessar Sistema</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0 bg-slate-50">
      <Header onLogout={handleLogout} user={authState.user} />

      {/* Confirmation Modal for Checkout */}
      {showCheckoutConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border border-slate-200">
            <div className="bg-amber-50 p-6 flex items-center justify-between border-b border-amber-100">
              <div className="flex items-center gap-3">
                <AlertTriangle className="w-6 h-6 text-amber-600" />
                <h3 className="font-black text-slate-800 uppercase tracking-tight">Confirmar Acautelamento</h3>
              </div>
              <button onClick={() => setShowCheckoutConfirm(false)} className="text-slate-400 hover:text-red-600 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-100">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Militar Responsável</p>
                    <p className="font-black text-slate-800 uppercase">{authState.user.rank} {authState.user.warName}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">BM</p>
                    <p className="font-bold text-slate-700 tracking-tighter">{authState.user.bm}</p>
                  </div>
                </div>

                <div className="pt-2">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Materiais Descritos</p>
                  <p className="text-sm text-slate-700 font-medium bg-white p-3 rounded-xl border border-slate-200 mt-1 italic">"{checkoutMaterial}"</p>
                </div>

                <div className="flex justify-between items-center pt-2">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Tipo</p>
                    <span className="inline-block px-2.5 py-1 bg-red-700 text-white text-[9px] font-black rounded-lg uppercase tracking-wider mt-1">{checkoutType}</span>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Previsto Para</p>
                    <p className="font-black text-red-600 flex items-center gap-1.5 justify-end">
                      <Calendar className="w-4 h-4" /> {formatDate(checkoutEstimatedReturn)}
                    </p>
                  </div>
                </div>
              </div>

              <div className="bg-red-50 p-4 rounded-xl border border-red-100 text-red-800 text-xs flex gap-3">
                <CheckCircle2 className="w-5 h-5 flex-shrink-0 mt-0.5" />
                <p className="font-medium leading-tight uppercase tracking-tight">Ao confirmar, você declara ter conferido todos os materiais e assume a responsabilidade pela guarda e conservação dos mesmos.</p>
              </div>

              <div className="flex flex-col sm:flex-row gap-3 pt-2">
                <button 
                  onClick={() => setShowCheckoutConfirm(false)}
                  className="flex-1 px-6 py-4 bg-slate-100 hover:bg-slate-200 text-slate-600 font-black rounded-2xl transition-all uppercase tracking-widest text-[10px]"
                >
                  Revisar Dados
                </button>
                <button 
                  onClick={handleCheckoutFinal}
                  className="flex-1 px-6 py-4 bg-green-600 hover:bg-green-700 text-white font-black rounded-2xl shadow-lg transition-all active:scale-95 uppercase tracking-widest text-[10px] border-b-4 border-green-800"
                >
                  Sim, Confirmar Registro
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8 space-y-6">
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40 overflow-x-auto no-scrollbar">
          {[
            { id: 'checkout', icon: PlusCircle, label: 'Acautelar' },
            { id: 'checkin', icon: ArrowRightLeft, label: 'Devolver' },
            { id: 'history', icon: History, label: 'Histórico' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-bold transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
              <tab.icon className="w-4 h-4" />
              <span className="text-xs uppercase tracking-tighter">{tab.label}</span>
            </button>
          ))}
        </div>

        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-red-50 p-3 rounded-2xl text-red-600 shadow-inner"><ClipboardList className="w-6 h-6" /></div>
                <div>
                  <h2 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Novo Acautelamento</h2>
                  <p className="text-xs text-slate-400 font-medium">Registre a saída de materiais</p>
                </div>
              </div>
              <form onSubmit={initiateCheckout} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Descrição</label>
                      <textarea placeholder="Liste os materiais..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl min-h-[140px] resize-none font-medium outline-none focus:ring-2 focus:ring-red-500" value={checkoutMaterial} onChange={(e) => setCheckoutMaterial(e.target.value)} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Previsão de Entrega</label>
                      <input type="date" min={todayStr} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none focus:ring-2 focus:ring-red-500" value={checkoutEstimatedReturn} onChange={(e) => setCheckoutEstimatedReturn(e.target.value)} required />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Tipo de Material</label>
                    <div className="grid grid-cols-1 gap-2">
                      {MATERIAL_TYPES.map(t => (
                        <button key={t} type="button" onClick={() => setCheckoutType(t)} className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${checkoutType === t ? 'border-red-600 bg-red-50 text-red-700 font-bold shadow-sm' : 'border-slate-200 bg-white text-slate-600'}`}>
                          <span className="text-sm uppercase tracking-tight">{t}</span>
                          {checkoutType === t && <CheckCircle2 className="w-4 h-4" />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-5 rounded-2xl shadow-xl uppercase tracking-widest text-sm border-b-4 border-red-900">Confirmar Registro</button>
              </form>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
                <div className="bg-green-50 p-3 rounded-2xl text-green-600 shadow-inner"><ArrowRightLeft className="w-6 h-6" /></div>
                <div>
                  <h2 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Devolução de Materiais</h2>
                  <p className="text-xs text-slate-400 font-medium">Localize o acautelamento pendente para registrar a entrada</p>
                </div>
              </div>
              <div className="space-y-4 pt-4">
                {movements.filter(m => m.status === MovementStatus.PENDENTE).length > 0 ? (
                  movements.filter(m => m.status === MovementStatus.PENDENTE).map(m => (
                    <CheckinItem 
                      key={m.id} 
                      movement={m} 
                      onReturn={handleReturn} 
                      overdue={isOverdue(m.estimatedReturnDate)} 
                    />
                  ))
                ) : (
                  <div className="text-center py-16 text-slate-300">
                    <ClipboardList className="w-12 h-12 mx-auto mb-2 opacity-20" />
                    <p className="font-bold uppercase text-xs tracking-widest">Nenhum acautelamento pendente</p>
                  </div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6">
              <div className="bg-gradient-to-br from-red-900 to-slate-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden group">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 relative z-10">
                  <div className="flex items-center gap-4">
                    <div className="bg-white/10 p-3 rounded-2xl backdrop-blur-md shadow-inner"><Sparkles className="w-6 h-6 text-yellow-400" /></div>
                    <div>
                      <h3 className="font-bold text-lg uppercase tracking-tight">Relatório Inteligente SAO</h3>
                      <p className="text-xs text-red-200 font-medium opacity-80">Análise de pendências via IA</p>
                    </div>
                  </div>
                  <button onClick={generateAiInsights} disabled={isLoadingAi} className="bg-white text-red-900 px-8 py-3 rounded-xl text-xs font-bold hover:bg-red-50 transition-all uppercase tracking-widest">{isLoadingAi ? 'ANALISANDO...' : 'GERAR ANÁLISE IA'}</button>
                </div>
                {aiSummary && <div className="mt-6 p-6 bg-white/5 backdrop-blur-xl rounded-2xl border border-white/10 text-sm leading-relaxed animate-in fade-in font-medium">{aiSummary}</div>}
              </div>

              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex flex-col md:flex-row gap-4 mb-8">
                  <div className="flex-1 relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input 
                      type="text" 
                      placeholder="Pesquisar militar, material, data (dd/mm/aaaa)..." 
                      className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-red-500 transition-all shadow-inner font-medium text-sm" 
                      value={searchTerm} 
                      onChange={(e) => setSearchTerm(e.target.value)} 
                    />
                  </div>
                  <div className="bg-slate-50 p-1 rounded-2xl border border-slate-200 flex min-w-fit">
                    {[
                      { id: 'all', label: 'Tudo' },
                      { id: MovementStatus.PENDENTE, label: 'Pendentes' },
                      { id: MovementStatus.DEVOLVIDO, label: 'Devolvidos' }
                    ].map(f => (
                      <button 
                        key={f.id} 
                        onClick={() => setStatusFilter(f.id as any)}
                        className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${statusFilter === f.id ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-100'}`}
                      >
                        {f.label}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="overflow-x-auto">
                  <table className="w-full text-left border-separate border-spacing-y-2">
                    <thead>
                      <tr>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest">Militar (Saída)</th>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest">Data Saída</th>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest">Material</th>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest text-center">Status</th>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest">Atestado Por</th>
                        <th className="pb-2 text-[10px] font-black text-slate-400 uppercase px-4 tracking-widest">Data Retorno</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredMovements.length > 0 ? (
                        filteredMovements.map(m => (
                          <tr key={m.id} className="bg-white hover:bg-slate-50 transition-all border border-slate-100 shadow-sm group">
                            <td className="py-4 px-4 rounded-l-2xl border-l border-y border-slate-100">
                              <p className="text-sm font-black text-slate-800 uppercase leading-none">{m.rank} {m.warName}</p>
                              <p className="text-[10px] text-slate-400 font-bold mt-1 tracking-tighter">BM: {m.bm}</p>
                            </td>
                            <td className="py-4 px-4 border-y border-slate-100">
                              <p className="text-xs text-slate-600 font-bold flex items-center gap-1.5"><Clock className="w-3.5 h-3.5 text-slate-300" /> {formatDateTime(m.dateCheckout)}</p>
                            </td>
                            <td className="py-4 px-4 border-y border-slate-100">
                              <p className="text-sm text-slate-700 font-medium max-w-[200px] truncate" title={m.material}>{m.material}</p>
                              <span className="text-[9px] font-black text-red-700 uppercase">{m.type}</span>
                            </td>
                            <td className="py-4 px-4 text-center border-y border-slate-100">
                              <span className={`inline-flex px-3 py-1 rounded-full text-[9px] font-black tracking-widest uppercase shadow-sm ${m.status === MovementStatus.PENDENTE ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-green-100 text-green-700 border border-green-200'}`}>
                                {m.status}
                              </span>
                            </td>
                            <td className="py-4 px-4 border-y border-slate-100">
                              {m.status === MovementStatus.DEVOLVIDO ? (
                                <div className="flex items-center gap-2">
                                  <div className="p-1.5 bg-green-50 rounded-lg text-green-600"><CheckCircle2 className="w-3 h-3" /></div>
                                  <div>
                                    <p className="text-[11px] font-black text-slate-800 uppercase leading-none">{m.receiverRank} {m.receiverWarName}</p>
                                    <p className="text-[9px] text-slate-400 font-bold mt-0.5">BM: {m.receiverBm}</p>
                                  </div>
                                </div>
                              ) : <span className="text-slate-300 italic text-[10px]">Aguardando...</span>}
                            </td>
                            <td className="py-4 px-4 rounded-r-2xl border-r border-y border-slate-100">
                              {m.status === MovementStatus.DEVOLVIDO ? (
                                <p className="text-xs text-slate-600 font-black flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5 text-green-400" /> {formatDateTime(m.dateReturn)}</p>
                              ) : <span className="text-slate-300 italic text-[10px]">-</span>}
                            </td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan={6} className="py-20 text-center text-slate-300">
                            <Search className="w-12 h-12 mx-auto mb-3 opacity-20" />
                            <p className="font-black uppercase text-xs tracking-widest">Nenhum registro encontrado para esta busca</p>
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer className="sm:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-200 px-6 py-3 flex justify-between items-center z-50 shadow-lg">
        {['checkout', 'checkin', 'history'].map((id) => (
          <button key={id} onClick={() => setActiveTab(id as any)} className={`flex flex-col items-center ${activeTab === id ? 'text-red-700 scale-110' : 'text-slate-400'}`}>
            {id === 'checkout' && <PlusCircle className="w-5 h-5" />}
            {id === 'checkin' && <ArrowRightLeft className="w-5 h-5" />}
            {id === 'history' && <History className="w-5 h-5" />}
            <span className="text-[8px] font-black mt-1 uppercase">{id === 'checkout' ? 'Acautelar' : id === 'checkin' ? 'Devolver' : 'Histórico'}</span>
          </button>
        ))}
      </footer>
    </div>
  );
};

export default App;

export enum MaterialType {
  TERRESTRE = "Salv. Terrestre/Altura",
  INCENDIO = "Incêndio Urbano",
  FLORESTAL = "Florestal",
  APH = "APH",
  AQUATICO = "Salv. Aquático",
  FERRAMENTAS = "Ferramentas diversas",
  OUTROS = "Outros"
}

export enum MovementStatus {
  PENDENTE = "PENDENTE",
  DEVOLVIDO = "DEVOLVIDO"
}

export interface MilitaryPerson {
  bm: string;
  name: string;
  warName: string;
  rank: string;
  cpf: string;
}

