                <button 
                  onClick={handleCheckoutFinal}
                  className="flex-1 px-6 py-4 bg-green-600 hover:bg-green-700 text-white font-black rounded-2xl shadow-lg transition-all active:scale-95 uppercase tracking-widest text-[10px] border-b-4 border-green-800"
                >
                  Sim, Confirmar Registro
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-6 lg:p-8 space-y-6">
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40 overflow-x-auto no-scrollbar">
          {[
            { id: 'checkout', icon: PlusCircle, label: 'Acautelar' },
            { id: 'checkin', icon: ArrowRightLeft, label: 'Devolver' },
            { id: 'history', icon: History, label: 'Histórico' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-bold transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
              <tab.icon className="w-4 h-4" />
              <span className="text-xs uppercase tracking-tighter">{tab.label}</span>
