                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex items-center gap-2">Motivo do Acautelamento <span className="text-[10px] text-slate-400 lowercase">(Opcional)</span></label>
                      <input type="text" placeholder="Ex: Treinamento, Ocorrência, Manutenção..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500" value={checkoutReason} onChange={(e) => setCheckoutReason(e.target.value)} />
