const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | MovementStatus>(MovementStatus.PENDENTE);
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Default date in 2026
  const default2026Date = useMemo(() => {
    const d = new Date();
    d.setFullYear(2026);
    return d.toISOString().split('T')[0];
  }, []);

  // Form State
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  // Checkout State
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutReason, setCheckoutReason] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState(default2026Date);
  const [showCheckoutConfirm, setShowCheckoutConfirm] = useState(false);

  const todayStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));
    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const warName = extractWarName(formName);
      const user: MilitaryPerson = { rank: formRank, name: formName, warName: warName, bm: formBm, cpf: '' };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else {
      alert("Por favor, preencha todos os campos de identificação.");
    }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName(''); setFormBm(''); setAiSummary(null);
  };

  const initiateCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    setShowCheckoutConfirm(true);
  };

  /**
   * Simulates sending institutional email notifications
   */
  const sendEmailNotification = (params: {
    type: 'CHECKOUT' | 'RETURN';
    recipient: MilitaryPerson;
    material: string;
    checkoutOwner?: { rank: string; name: string };
  }) => {
    const cleanBm = params.recipient.bm.replace(/\D/g, '');
    const recipientEmail = `${cleanBm}@bombeiros.mg.gov.br`;

    let emailBody = "";

    if (params.type === 'CHECKOUT') {
      emailBody = `Olá ${params.recipient.rank} ${params.recipient.name} registramos uma retirada de material na SAO do 6º BBM em seu nome (${params.material}), caso não reconheça fineza fazer contato com o militar da SAO de serviço hoje, para regularizar a situação.`;
    } else {
      emailBody = `Olá ${params.recipient.rank} ${params.recipient.name} registramos que você recebeu os seguintes materiais na SAO do 6º BBM acautelados por (${params.checkoutOwner?.rank} ${params.checkoutOwner?.name}): (${params.material}), caso não reconheça fineza fazer contato com o militar da SAO de serviço hoje, para regularizar a situação.`;
    }

    // Simulate async process
    console.log(`[EMAIL NOTIFICATION - ${params.type}] Sent to: ${recipientEmail}`);
    console.log(`[CONTENT]: ${emailBody}`);

    return { email: recipientEmail, body: emailBody };
  };

  const handleCheckoutFinal = () => {
    if (!authState.user) return;
    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm, name: authState.user.name, warName: authState.user.warName,
      rank: authState.user.rank, dateCheckout: new Date().toISOString(),
      estimatedReturnDate: checkoutEstimatedReturn, material: checkoutMaterial,
      reason: checkoutReason || undefined,
      type: checkoutType, status: MovementStatus.PENDENTE
    };

    setMovements([newMovement, ...movements]);

    // Email for the one who checked out
    const notification = sendEmailNotification({
      type: 'CHECKOUT',
      recipient: authState.user,
      material: checkoutMaterial
    });

    setCheckoutMaterial(''); setCheckoutReason(''); setCheckoutEstimatedReturn(default2026Date);
    setShowCheckoutConfirm(false);

    alert(`Material acautelado com sucesso!\n\nNotificação enviada para: ${notification.email}`);
    setActiveTab('history');
  };

  const handleReturn = (id: string, obs: string) => {
    if (!authState.user) return;

    let materialDesc = "";
    let checkoutRank = "";
    let checkoutName = "";

    setMovements(prev => prev.map(m => {
      if (m.id === id) {
        materialDesc = m.material;
        checkoutRank = m.rank;
        checkoutName = m.name;

        return {
          ...m, status: MovementStatus.DEVOLVIDO, dateReturn: new Date().toISOString(),
          observations: obs || 'Sem observações.', receiverBm: authState.user?.bm,
          receiverName: authState.user?.name, receiverWarName: authState.user?.warName,
          receiverRank: authState.user?.rank
        };
      }
      return m;
    }));

    // Email for the one who is receiving (the current user)
    const notification = sendEmailNotification({
      type: 'RETURN',
      recipient: authState.user,
      material: materialDesc,
      checkoutOwner: { rank: checkoutRank, name: checkoutName }
    });

    alert(`DEVOLUÇÃO ATESTADA COM SUCESSO!\n\nNotificação enviada para o receptor: ${notification.email}`);
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados para análise.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return movements.filter(m => {
      const matchesStatus = statusFilter === 'all' || m.status === statusFilter;
      const checkoutDateStr = formatDate(m.dateCheckout);
      const returnDateStr = m.dateReturn ? formatDateTime(m.dateReturn) : "";

      const searchFields = [
        m.name, 
        m.warName, 
        m.material, 
        m.bm, 
        m.type, 
        m.rank, 
        m.status,
        m.reason || "",
        checkoutDateStr,
        returnDateStr,
        m.receiverName || "",
        m.receiverWarName || ""
      ];

      const matchesSearch = searchFields.some(field => field.toLowerCase().includes(term));

      return matchesStatus && matchesSearch;
    });
  }, [movements, searchTerm, statusFilter]);

  const isOverdue = (dateStr?: string) => {
    if (!dateStr) return false;
    return new Date(`${dateStr}T23:59:59`) < new Date();
  };

  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-950 transition-all duration-700">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-500">
          <div className="bg-red-700 p-10 text-center text-white relative">
            <div className="absolute top-0 left-0 w-full h-1 bg-yellow-500"></div>
            <div className="mb-2">
              <h1 className="text-4xl font-black uppercase tracking-tighter leading-none drop-shadow-sm">SAO - 6º BBM</h1>
              <p className="text-[10px] font-bold mt-2 opacity-90 tracking-widest uppercase">Corpo de Bombeiros Militar de MG</p>
            </div>
          </div>
          <div className="p-8">
            <form onSubmit={handleIdentify} className="space-y-4">
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Posto/Graduação</label>
                <div className="relative">
                  <select className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl appearance-none font-medium outline-none focus:ring-2 focus:ring-red-500 transition-all" value={formRank} onChange={(e) => setFormRank(e.target.value)} required>
                    <option value="">Selecione...</option>
                    {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                  <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Nome Completo</label>
                <input type="text" placeholder="Ex: JOÃO Augusto Fernandes" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500 transition-all" value={formName} onChange={(e) => setFormName(e.target.value)} required />
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-bold text-slate-500 uppercase ml-1">Número BM</label>
                <input type="text" placeholder="Ex: 123.345-6" maxLength={10} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold tracking-widest outline-none focus:ring-2 focus:ring-red-500 transition-all" value={formBm} onChange={(e) => setFormBm(formatBM(e.target.value))} required />
              </div>
              <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-xl shadow-lg mt-4 uppercase tracking-widest text-sm border-b-4 border-red-900 transition-all active:scale-95">Acessar Sistema</button>
            </form>
          </div>
        </div>
        <p className="mt-6 text-white/40 text-[10px] font-black uppercase tracking-[0.2em]">Segurança e Agilidade no Apoio Operacional</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0 bg-slate-50">
      <Header onLogout={handleLogout} user={authState.user} />

      {/* Confirmation Modal for Checkout */}
      {showCheckoutConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 border border-slate-200">
            <div className="bg-amber-50 p-6 flex items-center justify-between border-b border-amber-100">
              <div className="flex items-center gap-3">
                <AlertTriangle className="w-6 h-6 text-amber-600" />
                <h3 className="font-black text-slate-800 uppercase tracking-tight">Confirmar Acautelamento</h3>
              </div>
              <button onClick={() => setShowCheckoutConfirm(false)} className="text-slate-400 hover:text-red-600 transition-colors">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-100">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Militar Responsável</p>
                    <p className="font-black text-slate-800 uppercase">{authState.user.rank} {authState.user.warName}</p>
                    <div className="flex items-center gap-1.5 mt-1">
                      <Mail className="w-3 h-3 text-red-500" />
                      <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tight">{authState.user.bm.replace(/\D/g, '')}@bombeiros.mg.gov.br</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">BM</p>
                    <p className="font-bold text-slate-700 tracking-tighter">{authState.user.bm}</p>
                  </div>
                </div>

                <div className="pt-2">
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Materiais Descritos</p>
                  <p className="text-sm text-slate-700 font-medium bg-white p-3 rounded-xl border border-slate-200 mt-1 italic">"{checkoutMaterial}"</p>
                </div>

