          <button onClick={onLogout} className="p-2 hover:bg-red-800 rounded-xl transition-all border border-transparent hover:border-red-500">
            <LogOut className="w-5 h-5" />
          </button>
        </div>
      )}
    </div>
  </header>
);

const CheckinItem: React.FC<{ 
  movement: Movement; 
  onReturn: (id: string, obs: string) => void;
  overdue: boolean;
  isProcessing: boolean;
}> = ({ movement, onReturn, overdue, isProcessing }) => {
  const [showForm, setShowForm] = useState(false);
  const [obs, setObs] = useState('');

  return (
    <div className={`bg-white border-2 rounded-2xl overflow-hidden hover:shadow-lg transition-all duration-300 ${overdue ? 'border-red-200 shadow-sm bg-red-50/10' : 'border-slate-100'}`}>
      <div className="p-5 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-5">
        <div className="flex-1 space-y-1">
          <div className="flex flex-wrap items-center gap-2 mb-2">
             <span className="px-2.5 py-1 bg-red-700 text-white text-[9px] font-black rounded-lg uppercase tracking-wider shadow-sm">{movement.type}</span>
             <div className="flex items-center gap-1 text-[10px] text-slate-400 font-bold uppercase">
               <Clock className="w-3 h-3" /> {formatDateTime(movement.dateCheckout)}
             </div>
             {movement.estimatedReturnDate && (
               <div className={`flex items-center gap-1 text-[10px] font-black uppercase px-2 py-0.5 rounded border ${overdue ? 'text-red-600 border-red-200 bg-red-50 animate-pulse' : 'text-slate-500 border-slate-200 bg-slate-50'}`}>
                 <Calendar className="w-3 h-3" /> Previsto: {formatDate(movement.estimatedReturnDate)}
               </div>
             )}
          </div>
          <h4 className="font-black text-slate-800 text-lg uppercase tracking-tight">{movement.rank} {movement.warName}</h4>
          <p className="text-sm text-slate-600 mt-1 italic font-medium leading-relaxed bg-slate-50 p-2 rounded-xl border border-slate-100">"{movement.material}"</p>
          {movement.reason && <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tight mt-1 flex items-center gap-1"><Info className="w-3 h-3" /> Motivo: {movement.reason}</p>}
        </div>
        <button 
          onClick={() => setShowForm(!showForm)}
          disabled={isProcessing}
          className={`${overdue ? 'bg-red-700 hover:bg-red-800' : 'bg-green-600 hover:bg-green-700'} text-white font-black px-8 py-3 rounded-2xl text-xs sm:text-sm transition-all shadow-md flex items-center gap-2 active:scale-95 border-b-4 ${overdue ? 'border-red-900' : 'border-green-800'} disabled:opacity-50`}
        >
          {showForm ? 'CANCELAR' : 'REGISTRAR DEVOLUÇÃO'}
        </button>
      </div>

      {showForm && (
        <div className="px-5 pb-5 bg-slate-50 border-t-2 border-slate-100 animate-in slide-in-from-top-4 duration-300">
          <div className="pt-5 space-y-4">
            <div className="flex justify-between items-center">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                <AlertTriangle className="w-3 h-3 text-red-500" /> Observações (Avarias, pendências, etc.)
              </label>
            </div>
            <textarea 
              className="w-full p-4 bg-white border-2 border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-green-500 font-medium transition-all shadow-inner placeholder:text-slate-300 min-h-[100px]"
              placeholder="Descreva se o material está avariado ou se a devolução é parcial..."
              value={obs}
              onChange={(e) => setObs(e.target.value)}
            />
            <div className="flex justify-end">
              <button 
                onClick={() => {
                  onReturn(movement.id, obs);
                  setShowForm(false);
                }}
                disabled={isProcessing}
                className="bg-green-700 text-white px-10 py-4 rounded-2xl text-xs font-black hover:bg-green-800 transition-all shadow-xl active:scale-95 uppercase tracking-widest border-b-4 border-green-900 flex items-center gap-2 disabled:bg-slate-400 disabled:border-slate-500"
              >
                {isProcessing ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle2 className="w-4 h-4" />}
                {isProcessing ? 'ENVIANDO E-MAIL...' : 'Atestar Recebimento Agora'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<'all' | MovementStatus>(MovementStatus.PENDENTE);
  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);
  const [isProcessingEmail, setIsProcessingEmail] = useState(false);

  const default2026Date = useMemo(() => {
    const d = new Date();
    d.setFullYear(2026);
    return d.toISOString().split('T')[0];
  }, []);

  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');

  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutReason, setCheckoutReason] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState(default2026Date);
  const [showCheckoutConfirm, setShowCheckoutConfirm] = useState(false);

  const todayStr = useMemo(() => new Date().toISOString().split('T')[0], []);

  useEffect(() => {
    const saved = localStorage.getItem('sao_movements');
    if (saved) setMovements(JSON.parse(saved));
    const savedUser = localStorage.getItem('sao_current_user');
    if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });

    // Inicializa o EmailJS com a Public Key fornecida
    emailjs.init(EMAILJS_CONFIG.PUBLIC_KEY);
  }, []);

  useEffect(() => {
    localStorage.setItem('sao_movements', JSON.stringify(movements));
  }, [movements]);

  const handleIdentify = (e: React.FormEvent) => {
    e.preventDefault();
    if (formRank && formName && formBm) {
      const warName = extractWarName(formName);
      const user: MilitaryPerson = { rank: formRank, name: formName, warName: warName, bm: formBm, cpf: '' };
      setAuthState({ user, isVisitor: false });
      localStorage.setItem('sao_current_user', JSON.stringify(user));
    } else { alert("Preencha os campos."); }
  };

  const handleLogout = () => {
    setAuthState({ user: null, isVisitor: false });
    localStorage.removeItem('sao_current_user');
    setFormName(''); setFormBm(''); setAiSummary(null);
  };

  const initiateCheckout = (e: React.FormEvent) => {
    e.preventDefault();
    setShowCheckoutConfirm(true);
  };

  const sendRealEmail = async (params: {
    type: 'CHECKOUT' | 'RETURN';
    recipient: MilitaryPerson;
    material: string;
    checkoutOwner?: { rank: string; name: string };
  }) => {
    const cleanBm = params.recipient.bm.replace(/\D/g, '');
    const recipientEmail = `${cleanBm}@bombeiros.mg.gov.br`;

    let message = "";
    if (params.type === 'CHECKOUT') {
      message = `Olá ${params.recipient.rank} ${params.recipient.name}, registramos uma retirada de material na SAO do 6º BBM em seu nome (${params.material}). Caso não reconheça, favor fazer contato com o militar da SAO de serviço hoje para regularizar a situação.`;
    } else {
      message = `Olá ${params.recipient.rank} ${params.recipient.name}, registramos que você recebeu os seguintes materiais na SAO do 6º BBM acautelados por (${params.checkoutOwner?.rank} ${params.checkoutOwner?.name}): (${params.material}). Caso não reconheça, favor fazer contato com o militar da SAO de serviço hoje para regularizar a situação.`;
    }

    try {
      setIsProcessingEmail(true);
      await emailjs.send(
        EMAILJS_CONFIG.SERVICE_ID,
        EMAILJS_CONFIG.TEMPLATE_ID,
        {
          to_email: recipientEmail,
          message: message,
          subject: params.type === 'CHECKOUT' ? 'Notificação de Acautelamento - 6º BBM' : 'Notificação de Devolução - 6º BBM'
        }
      );
      console.log(`[EMAIL] Enviado para ${recipientEmail}`);
      return true;
    } catch (error) {
      console.error("[EMAIL ERROR]", error);
      return false;
    } finally {
      setIsProcessingEmail(false);
    }
  };

  const handleCheckoutFinal = async () => {
    if (!authState.user) return;
    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm, name: authState.user.name, warName: authState.user.warName,
      rank: authState.user.rank, dateCheckout: new Date().toISOString(),
      estimatedReturnDate: checkoutEstimatedReturn, material: checkoutMaterial,
      reason: checkoutReason || undefined,
      type: checkoutType, status: MovementStatus.PENDENTE
    };

    const emailSent = await sendRealEmail({
      type: 'CHECKOUT',
      recipient: authState.user,
      material: checkoutMaterial
    });

    setMovements([newMovement, ...movements]);
    setCheckoutMaterial(''); setCheckoutReason(''); setCheckoutEstimatedReturn(default2026Date);
    setShowCheckoutConfirm(false);

    const statusMsg = emailSent 
      ? `Material acautelado e e-mail enviado para: ${authState.user.bm.replace(/\D/g, '')}@bombeiros.mg.gov.br`
      : "Material registrado, mas houve um erro ao disparar o e-mail. Verifique a conexão do Gmail no EmailJS.";

    alert(statusMsg);
    setActiveTab('history');
  };

  const handleReturn = async (id: string, obs: string) => {
    if (!authState.user) return;

    const targetMovement = movements.find(m => m.id === id);
    if (!targetMovement) return;

    const emailSent = await sendRealEmail({
      type: 'RETURN',
      recipient: authState.user,
      material: targetMovement.material,
      checkoutOwner: { rank: targetMovement.rank, name: targetMovement.name }
    });

    setMovements(prev => prev.map(m => {
      if (m.id === id) {
        return {
          ...m, status: MovementStatus.DEVOLVIDO, dateReturn: new Date().toISOString(),
          observations: obs || 'Sem observações.', receiverBm: authState.user?.bm,
          receiverName: authState.user?.name, receiverWarName: authState.user?.warName,
          receiverRank: authState.user?.rank
        };
      }
      return m;
    }));

    const statusMsg = emailSent 
      ? `Devolução registrada e e-mail de recebimento enviado para: ${authState.user.bm.replace(/\D/g, '')}@bombeiros.mg.gov.br`
      : "Devolução registrada, mas houve um erro no envio do e-mail institucional.";

    alert(statusMsg);
  };

  const generateAiInsights = async () => {
    setIsLoadingAi(true);
    const summary = await getSmartSummary(movements);
    setAiSummary(summary || "Sem dados.");
    setIsLoadingAi(false);
  };

  const filteredMovements = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return movements.filter(m => {
      const matchesStatus = statusFilter === 'all' || m.status === statusFilter;
      const searchFields = [m.name, m.material, m.bm, m.rank, m.status, m.reason || ""];
      const matchesSearch = searchFields.some(field => field.toLowerCase().includes(term));
      return matchesStatus && matchesSearch;
    });
  }, [movements, searchTerm, statusFilter]);

  const isOverdue = (dateStr?: string) => {
    if (!dateStr) return false;
    return new Date(`${dateStr}T23:59:59`) < new Date();
  };

  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-950">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden border border-slate-200 animate-in fade-in zoom-in-95 duration-500">
          <div className="bg-red-700 p-10 text-center text-white relative">
            <h1 className="text-4xl font-black uppercase tracking-tighter leading-none">SAO - 6º BBM</h1>
            <p className="text-[10px] font-bold mt-2 opacity-90 tracking-widest uppercase">Corpo de Bombeiros Militar de MG</p>
          </div>
          <div className="p-8">
            <form onSubmit={handleIdentify} className="space-y-4">
              <select className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500" value={formRank} onChange={(e) => setFormRank(e.target.value)} required>
                <option value="">Selecione Posto/Grad...</option>
                {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
              <input type="text" placeholder="Ex: JOÃO Augusto Fernandes" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500" value={formName} onChange={(e) => setFormName(e.target.value)} required />
              <input type="text" placeholder="Ex: 100.321-6" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold tracking-widest outline-none focus:ring-2 focus:ring-red-500" value={formBm} onChange={(e) => setFormBm(formatBM(e.target.value))} required />
              <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-4 rounded-xl shadow-lg mt-4 uppercase tracking-widest border-b-4 border-red-900 transition-all active:scale-95">Acessar Sistema</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col pb-20 sm:pb-0 bg-slate-50">
      <Header onLogout={handleLogout} user={authState.user} />

      {showCheckoutConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden border border-slate-200">
            <div className="bg-amber-50 p-6 flex items-center justify-between border-b border-amber-100">
              <div className="flex items-center gap-3">
                <AlertTriangle className="w-6 h-6 text-amber-600" />
                <h3 className="font-black text-slate-800 uppercase tracking-tight">Confirmar Acautelamento</h3>
              </div>
              <button onClick={() => setShowCheckoutConfirm(false)} className="text-slate-400 hover:text-red-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-8 space-y-6">
              <div className="bg-slate-50 p-6 rounded-2xl space-y-4 border border-slate-100 text-sm font-medium">
                <p><span className="text-slate-400 uppercase text-[10px] font-bold block">Responsável</span> {authState.user.rank} {authState.user.warName} ({authState.user.bm})</p>
                <p><span className="text-slate-400 uppercase text-[10px] font-bold block">Material</span> {checkoutMaterial}</p>
                <p className="flex justify-between">
                  <span><span className="text-slate-400 uppercase text-[10px] font-bold block">Tipo</span> {checkoutType}</span>
                  <span className="text-right text-red-600 font-bold"><span className="text-slate-400 uppercase text-[10px] font-bold block">Entrega</span> {formatDate(checkoutEstimatedReturn)}</span>
                </p>
              </div>

              <div className="bg-red-50 p-4 rounded-xl border border-red-100 text-red-800 text-xs flex gap-3">
                <Mail className="w-5 h-5 flex-shrink-0" />
                <p>Uma notificação institucional será enviada agora para <b>{authState.user.bm.replace(/\D/g, '')}@bombeiros.mg.gov.br</b> via Gmail.</p>
              </div>

              <div className="flex gap-3">
                <button onClick={() => setShowCheckoutConfirm(false)} className="flex-1 px-6 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px]">Revisar</button>
                <button 
                  onClick={handleCheckoutFinal} 
                  disabled={isProcessingEmail}
                  className="flex-1 px-6 py-4 bg-green-600 hover:bg-green-700 text-white font-black rounded-2xl shadow-lg transition-all uppercase text-[10px] border-b-4 border-green-800 flex items-center justify-center gap-2"
                >
                  {isProcessingEmail && <Loader2 className="w-4 h-4 animate-spin" />}
                  {isProcessingEmail ? 'ENVIANDO...' : 'Confirmar e Notificar'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-8 space-y-6">
        <div className="flex bg-white rounded-2xl shadow-sm border border-slate-200 p-1 sticky top-20 z-40 overflow-x-auto">
          {[
            { id: 'checkout', icon: PlusCircle, label: 'Acautelar' },
            { id: 'checkin', icon: ArrowRightLeft, label: 'Devolver' },
            { id: 'history', icon: History, label: 'Histórico' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-2 py-3 px-4 rounded-xl font-bold transition-all ${activeTab === tab.id ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>
              <tab.icon className="w-4 h-4" />
              <span className="text-xs uppercase tracking-tighter">{tab.label}</span>
            </button>
          ))}
        </div>

        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6">
                <div className="bg-red-50 p-3 rounded-2xl text-red-600 shadow-inner"><ClipboardList className="w-6 h-6" /></div>
                <div>
                  <h2 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Novo Acautelamento</h2>
                  <p className="text-xs text-slate-400 font-medium italic">O e-mail será enviado automaticamente via Gmail integrado.</p>
                </div>
              </div>
              <form onSubmit={initiateCheckout} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-6">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Descrição do Material</label>
                      <textarea placeholder="Liste os materiais..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl min-h-[140px] resize-none font-medium outline-none focus:ring-2 focus:ring-red-500" value={checkoutMaterial} onChange={(e) => setCheckoutMaterial(e.target.value)} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Motivo do Uso</label>
                      <input type="text" placeholder="Ex: Treinamento, Ocorrência..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium outline-none focus:ring-2 focus:ring-red-500" value={checkoutReason} onChange={(e) => setCheckoutReason(e.target.value)} />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Previsão de Devolução</label>
                      <input type="date" min={todayStr} className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold outline-none focus:ring-2 focus:ring-red-500" value={checkoutEstimatedReturn} onChange={(e) => setCheckoutEstimatedReturn(e.target.value)} required />
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Tipo de Material</label>
                    <div className="grid grid-cols-1 gap-2">
                      {MATERIAL_TYPES.map(t => (
                        <button key={t} type="button" onClick={() => setCheckoutType(t)} className={`flex items-center justify-between px-4 py-3 rounded-2xl border transition-all ${checkoutType === t ? 'border-red-600 bg-red-50 text-red-700 font-bold' : 'border-slate-200 bg-white text-slate-600'}`}>
                          <span className="text-sm uppercase tracking-tight">{t}</span>
                          {checkoutType === t && <CheckCircle2 className="w-4 h-4" />}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
                <button type="submit" className="w-full bg-red-700 hover:bg-red-800 text-white font-bold py-5 rounded-2xl shadow-xl uppercase tracking-widest text-sm border-b-4 border-red-900">Registrar e Disparar Notificação</button>
              </form>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
              <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
                <div className="bg-green-50 p-3 rounded-2xl text-green-600 shadow-inner"><ArrowRightLeft className="w-6 h-6" /></div>
                <h2 className="text-xl font-bold text-slate-800 uppercase tracking-tight">Devolução de Materiais</h2>
              </div>
              <div className="space-y-4 pt-4">
                {movements.filter(m => m.status === MovementStatus.PENDENTE).length > 0 ? (
                  movements.filter(m => m.status === MovementStatus.PENDENTE).map(m => (
                    <CheckinItem key={m.id} movement={m} onReturn={handleReturn} overdue={isOverdue(m.estimatedReturnDate)} isProcessing={isProcessingEmail} />
                  ))
                ) : (
                  <div className="text-center py-16 text-slate-300 uppercase font-black text-xs tracking-widest">Nenhum acautelamento pendente</div>
                )}
              </div>
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6">
              <div className="bg-gradient-to-br from-red-900 to-slate-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden group">
                <div className="flex justify-between items-center gap-4 relative z-10">
                  <div className="flex items-center gap-4">
                    <div className="bg-white/10 p-3 rounded-2xl shadow-inner"><Sparkles className="w-6 h-6 text-yellow-400" /></div>
                    <h3 className="font-bold text-lg uppercase tracking-tight">Relatório Inteligente SAO</h3>
                  </div>
                  <button onClick={generateAiInsights} disabled={isLoadingAi} className="bg-white text-red-900 px-8 py-3 rounded-xl text-xs font-bold hover:bg-red-50 transition-all uppercase tracking-widest">{isLoadingAi ? 'ANALISANDO...' : 'GERAR ANÁLISE IA'}</button>
                </div>
                {aiSummary && <div className="mt-6 p-6 bg-white/5 backdrop-blur-xl rounded-2xl border border-white/10 text-sm animate-in fade-in">{aiSummary}</div>}
              </div>

              <div className="bg-white rounded-3xl p-6 sm:p-8 shadow-sm border border-slate-200">
                <div className="flex flex-col md:flex-row gap-4 mb-8">
                  <div className="flex-1 relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-400" />
                    <input type="text" placeholder="Pesquisar..." className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-red-500 font-medium text-sm" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                  </div>
                  <div className="bg-slate-50 p-1 rounded-2xl border border-slate-200 flex min-w-fit">
                    {['all', MovementStatus.PENDENTE, MovementStatus.DEVOLVIDO].map(f => (
                      <button key={f} onClick={() => setStatusFilter(f as any)} className={`px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${statusFilter === f ? 'bg-red-700 text-white shadow-md' : 'text-slate-500 hover:bg-slate-100'}`}>{f === 'all' ? 'Tudo' : f}</button>
                    ))}
