                </div>
                {aiSummary && (
                  <div className="mt-8 p-6 bg-white/5 backdrop-blur-md rounded-2xl border border-white/10 text-sm leading-relaxed animate-in fade-in duration-700">
                    {aiSummary}
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

