          receiverName: authState.user?.name, receiverRank: authState.user?.rank,
          receiverWarName: authState.user?.warName
        };
      }
      return m;
    });
    setMovements(updated);
    await syncToSheets(updated);

    const target = movements.find(m => m.id === id);
