export const saveToSheets = async (url: string, movements: Movement[]) => {
  if (!url || url.includes("exec") === false) return false;

  try {
    // Usamos POST para salvar o estado completo
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify({ action: 'save', movements }),
      headers: { 'Content-Type': 'text/plain;charset=utf-8' }, // GAS lida melhor com text/plain
    });
    return true; // no-cors não permite ler a resposta, mas o disparo é feito
  } catch (error) {
    console.error("Erro ao salvar na planilha:", error);
    return false;
  }
};

export const fetchFromSheets = async (url: string): Promise<Movement[] | null> => {
  if (!url || url.includes("exec") === false) return null;

  try {
    const response = await fetch(`${url}?action=read&t=${Date.now()}`); // Previne cache
    if (!response.ok) throw new Error("Erro na rede");
    const data = await response.json();
    return data as Movement[];
  } catch (error) {
    console.error("Erro ao buscar da planilha:", error);
    return null;
  }
};

