          setSyncError(true);
        }
        setIsSyncing(false);
      }

      emailjs.init(EMAILJS_CONFIG.PUBLIC_KEY);
    };

    initApp();
  }, [sheetUrl]);

  const handleSyncManually = async () => {
    setIsSyncing(true);
    const data = await fetchFromSheets(sheetUrl);
