} from 'lucide-react';

const PERMANENT_SHEET_URL = "https://script.google.com/macros/s/AKfycbzlAE_yo3o6mo7X-4x4oeE0zD8S16gbqi0zEty5IyebTE7ww178_u1g8bOdffB_ApEt/exec";

// Configuração atualizada com a chave fornecida pelo usuário
const EMAILJS_CONFIG = {
  SERVICE_ID: "TESTE SAO", 
  TEMPLATE_ID: "template_epzy7h4", 
  PUBLIC_KEY: "E0VFVhDaGcvZiH2zD"
};

const formatBM = (value: string): string => {
  if (!value) return "";
  const digits = value.replace(/\D/g, '').slice(0, 7);
  if (digits.length > 6) return `${digits.slice(0, 3)}.${digits.slice(3, 6)}-${digits.slice(6)}`;
  if (digits.length > 3) return `${digits.slice(0, 3)}.${digits.slice(3)}`;
  return digits;
};

const formatDateTime = (dateStr?: string) => {
  if (!dateStr) return "-";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(d);
  } catch { return dateStr; }
};

interface Notification {
  message: string;
  type: 'success' | 'error';
  id: number;
}

const App: React.FC = () => {
  const [authState, setAuthState] = useState<AuthState>({ user: null, isVisitor: false });
  const [activeTab, setActiveTab] = useState<'checkout' | 'checkin' | 'history'>('checkout');
  const [movements, setMovements] = useState<Movement[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [checkinSearchTerm, setCheckinSearchTerm] = useState(''); 
  const [statusFilter, setStatusFilter] = useState<'all' | MovementStatus>(MovementStatus.PENDENTE);

  const [sheetUrl, setSheetUrl] = useState<string>(localStorage.getItem('sao_sheet_url') || PERMANENT_SHEET_URL);
  const [isSyncing, setIsSyncing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showConfig, setShowConfig] = useState(false);
  const [lastSync, setLastSync] = useState<string | null>(null);
  const [syncError, setSyncError] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [hasInitialLoad, setHasInitialLoad] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [aiSummary, setAiSummary] = useState<string | null>(null);
  const [isLoadingAi, setIsLoadingAi] = useState(false);

  // Form states
  const [formRank, setFormRank] = useState('');
  const [formName, setFormName] = useState('');
  const [formBm, setFormBm] = useState('');
  const [checkoutMaterial, setCheckoutMaterial] = useState('');
  const [checkoutReason, setCheckoutReason] = useState('');
  const [checkoutType, setCheckoutType] = useState<MaterialType>(MaterialType.TERRESTRE);
  const [checkoutEstimatedReturn, setCheckoutEstimatedReturn] = useState(() => {
    const d = new Date();
    d.setDate(d.getDate() + 7);
    return d.toISOString().split('T')[0];
  });

  const [showCheckoutConfirm, setShowCheckoutConfirm] = useState(false);
  const [pendingObservations, setPendingObservations] = useState<Record<string, string>>({});
  const [returnTarget, setReturnTarget] = useState<Movement | null>(null);
  const [showReturnConfirm, setShowReturnConfirm] = useState(false);

  // Função para adicionar notificações visuais (Toasts)
  const addNotification = (message: string, type: 'success' | 'error' = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { message, type, id }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  // Função para envio de e-mail automatizado via EmailJS
  const sendMovementEmail = async (toBm: string, messageBody: string, subjectTitle: string) => {
    // Monta o e-mail no formato: numeroBM@bombeiros.mg.gov.br (removendo pontos e traços)
    const email = `${toBm.replace(/\D/g, '')}@bombeiros.mg.gov.br`;

    try {
      // De acordo com a documentação do @emailjs/browser, o envio deve conter os parâmetros da template
      await emailjs.send(
        EMAILJS_CONFIG.SERVICE_ID,
        EMAILJS_CONFIG.TEMPLATE_ID,
        {
          to_email: email,
          subject: subjectTitle,
          message: messageBody,
          // Caso a template use outros nomes de campos:
          user_email: email,
          content: messageBody
        },
        EMAILJS_CONFIG.PUBLIC_KEY
      );
      console.log(`E-mail de notificação enviado para: ${email}`);
      addNotification(`E-mail enviado para ${email}`, 'success');
    } catch (error) {
      console.error("Falha ao enviar e-mail via EmailJS:", error);
      addNotification(`Falha ao enviar e-mail para ${email}. Verifique a configuração da chave.`, 'error');
    }
  };

  const syncData = useCallback(async (showLoader = true) => {
    if (showLoader) setIsSyncing(true);
    const data = await fetchFromSheets(sheetUrl);
    if (data) {
      setMovements(data);
      localStorage.setItem('sao_movements', JSON.stringify(data));
      setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));
      setSyncError(false);
      setHasInitialLoad(true);
    } else {
      setSyncError(true);
      const cached = localStorage.getItem('sao_movements');
      if (cached && !hasInitialLoad) {
        setMovements(JSON.parse(cached));
        setHasInitialLoad(true);
      }
    }
    if (showLoader) setIsSyncing(false);
  }, [sheetUrl, hasInitialLoad]);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const initApp = async () => {
      const savedUser = localStorage.getItem('sao_current_user');
      if (savedUser) setAuthState({ user: JSON.parse(savedUser), isVisitor: false });
      await syncData();
      // Inicializa o EmailJS com a chave pública
      emailjs.init(EMAILJS_CONFIG.PUBLIC_KEY);
    };

    initApp();

    const autoSyncInterval = setInterval(() => {
      if (navigator.onLine) syncData(false);
    }, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(autoSyncInterval);
    };
  }, [syncData]);

  const handleSyncManually = () => syncData(true);

  const handleCheckoutFinal = async () => {
    if (!authState.user || !hasInitialLoad) return;
    setIsSaving(true);

    const newMovement: Movement = {
      id: Math.random().toString(36).substr(2, 9),
      bm: authState.user.bm, 
      name: authState.user.name, 
      warName: authState.user.warName,
      rank: authState.user.rank, 
      dateCheckout: new Date().toISOString(),
      estimatedReturnDate: checkoutEstimatedReturn, 
      material: checkoutMaterial,
      reason: checkoutReason || 'Não informado', 
      type: checkoutType, 
      status: MovementStatus.PENDENTE
    };

    const updated = [newMovement, ...movements];
    setMovements(updated);
    localStorage.setItem('sao_movements', JSON.stringify(updated));

    const success = await saveToSheets(sheetUrl, updated);
    if (success) {
      setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));
      setSyncError(false);

      // MENSAGEM DE E-MAIL SOLICITADA (SAÍDA)
      const emailMessage = `Olá (${authState.user.rank} ${authState.user.name}) registramos uma retirada de material na SAO do 6º BBM em seu nome (${checkoutMaterial}), caso não reconheça fineza fazer contato com o militar da SAO de serviço hoje, para regularizar a situação`;

      await sendMovementEmail(authState.user.bm, emailMessage, "Retirada de Material - SAO 6º BBM");
    } else {
      setSyncError(true);
      addNotification("Erro ao salvar na planilha. E-mail não enviado.", "error");
    }

    setCheckoutMaterial(''); 
    setCheckoutReason(''); 
    setShowCheckoutConfirm(false);
    setIsSaving(false);
    setActiveTab('history');
  };

  const handleReturnFinal = async () => {
    if (!authState.user || !returnTarget || !hasInitialLoad) return;
    setIsSaving(true);
    const obs = pendingObservations[returnTarget.id] || 'Sem observações.';

    const updated = movements.map(m => {
      if (m.id === returnTarget.id) {
        return {
          ...m, 
          status: MovementStatus.DEVOLVIDO, 
          dateReturn: new Date().toISOString(),
          observations: obs, 
          receiverBm: authState.user?.bm,
          receiverName: authState.user?.name, 
          receiverRank: authState.user?.rank,
          receiverWarName: authState.user?.warName
        };
      }
      return m;
    });

    setMovements(updated);
    localStorage.setItem('sao_movements', JSON.stringify(updated));

    const success = await saveToSheets(sheetUrl, updated);
    if (success) {
      setLastSync(new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));
      setSyncError(false);

      // MENSAGEM DE E-MAIL SOLICITADA (RECEBIMENTO)
      // O e-mail vai para quem está logado (o militar da SAO que atestou o recebimento)
      const emailMessage = `Olá ${authState.user.rank} ${authState.user.name} registramos que você recebeu os seguintes materiais na SAO do 6º BBM acautelados por ${returnTarget.rank} ${returnTarget.name}: (${returnTarget.material}), caso não reconheça fineza fazer contato com o militar da SAO de serviço hoje, para regularizar a situação`;

      await sendMovementEmail(authState.user.bm, emailMessage, "Recebimento de Material - SAO 6º BBM");
    } else {
      setSyncError(true);
      addNotification("Erro ao salvar na planilha. E-mail não enviado.", "error");
    }

    setReturnTarget(null);
    setShowReturnConfirm(false);
    setIsSaving(false);
  };

  const filteredMovements = useMemo(() => {
    const term = (searchTerm || '').toLowerCase();
    return movements.filter(m => {
      const matchesStatus = statusFilter === 'all' || m.status === statusFilter;
      const matchesSearch = [
        m.name || '', 
        m.material || '', 
        m.bm || '', 
        m.reason || ''
      ].some(f => f.toLowerCase().includes(term));
      return matchesStatus && matchesSearch;
    });
  }, [movements, searchTerm, statusFilter]);

  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-950">
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500">
