export const saveToSheets = async (url: string, movements: Movement[]) => {
  if (!url || !url.includes("exec")) {
    console.error("URL da planilha inválida ou não configurada.");
    return false;
  }

  try {
    // IMPORTANTE: Removemos 'no-cors'. O modo padrão 'cors' é necessário para 
    // que o navegador envie o corpo do JSON corretamente para o Google Apps Script
    // e para que possamos ler a resposta de sucesso.
    const response = await fetch(url, {
      method: 'POST',
      body: JSON.stringify({ action: 'save', movements }),
      headers: { 
        'Content-Type': 'text/plain;charset=utf-8' 
      },
    });

    // Como o Google redireciona (302), o fetch segue o redirecionamento.
    // Se chegar aqui sem erro de rede, o GAS processou a requisição.
    return response.ok;
  } catch (error) {
    console.error("Erro crítico ao salvar na planilha:", error);
    return false;
  }
};

export const fetchFromSheets = async (url: string): Promise<Movement[] | null> => {
  if (!url || !url.includes("exec")) return null;

  try {
    const response = await fetch(`${url}?action=read&t=${Date.now()}`);
    if (!response.ok) {
      throw new Error(`Erro na rede: ${response.status}`);
    }
    const data = await response.json();

    // Garante que retornamos null se não for um array (erro no script)
    if (!Array.isArray(data)) {
      console.error("Dados recebidos da planilha não são um array:", data);
      return null;
    }

    return data as Movement[];
  } catch (error) {
    console.error("Erro crítico ao buscar dados da planilha:", error);
    return null;
  }
};
